const OLD_DEFAULT_FAR_TOPIC_IDS = new Set(["far-framework", "far-conceptual-fs", "far-cash", "far-financial-assets", "far-ppe", "far-nonfinancial-assets", "far-liabilities", "far-equity", "far-other-topics", "far-reporting-frameworks"]);
const DEFAULT_SUBJECT_TOPICS = topics.map(topic => JSON.parse(JSON.stringify(topic)));

function initializeSubjectTopics() {
  const legacyTopicIds = new Set(["debt", "inventory", "ppe"]);
  topics = topics
    .filter(topic => !legacyTopicIds.has(topic.id))
    .filter(topic => !OLD_DEFAULT_FAR_TOPIC_IDS.has(topic.id))
    .map(topic => ({ ...ensureTopicShape(topic), subject: topic.subject || "FAR" }));
  const existing = new Set(topics.map(t => t.id));
  DEFAULT_SUBJECT_TOPICS.forEach(t => {
    if (!existing.has(t.id)) topics.push({ ...JSON.parse(JSON.stringify(t)), tabs: Array.isArray(t.tabs) ? t.tabs : [], standard: t.standard || "", summary: t.summary || "", formula: t.formula || "", computation: t.computation || "" });
  });
}


function initializeQuestionSubjects() {
  const topicSubjectMap = Object.fromEntries(topics.map(t => [t.id, t.subject || "FAR"]));
  const legacyTopicMap = { debt: "far-financial-assets", inventory: "far-inventories", ppe: "far-ppe" };
  quizBank = quizBank.map((q, index) => {
    const topic = legacyTopicMap[q.topic] || q.topic || "far-inventories";
    return { ...q, topic, subject: q.subject || topicSubjectMap[topic] || "FAR", id: q.id || `local-q-${index + 1}-${Date.now()}` };
  });
}

