function slugify(value) {
  return String(value || "topic")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || `topic-${Date.now()}`;
}

function normalizeSubLessonTabs(subtabs = []) {
  return Array.isArray(subtabs)
    ? subtabs.filter(Boolean).map((subtab, index) => ({
        id: String(subtab.id || slugify(subtab.title || `sub-lesson-${index + 1}`)).trim(),
        title: String(subtab.title || "Untitled Sub-Lesson").trim(),
        content: String(subtab.content || "").trim(),
        createdAt: subtab.createdAt || new Date().toISOString(),
        updatedAt: subtab.updatedAt
      }))
    : [];
}

function ensureTopicShape(topic) {
  if (!topic) return topic;
  topic.tabs = Array.isArray(topic.tabs) ? topic.tabs : [];
  topic.tabs = topic.tabs.map((tab, index) => ({
    id: String(tab.id || slugify(tab.title || `lesson-tab-${index + 1}`)).trim(),
    title: String(tab.title || "Untitled Lesson Tab").trim(),
    content: String(tab.content || "").trim(),
    createdAt: tab.createdAt || new Date().toISOString(),
    updatedAt: tab.updatedAt,
    subtabs: normalizeSubLessonTabs(tab.subtabs || [])
  }));
  return topic;
}

const accountingTemplates = {
  tAccount: `[T-ACCOUNT]
Account Title: ____________________

Debit | Credit
₱__________ | ₱__________
₱__________ | ₱__________
₱__________ | ₱__________
₱__________ | ₱__________
[/T-ACCOUNT]`,
  accountingFormat: `[ACCOUNTING-FORMAT]
Company Name: ____________________
Computation Title: ____________________
For the period ended: ____________________

Particulars | Amount
____________________ | ₱__________
____________________ | ₱__________
____________________ | ₱__________

Final Answer | ₱__________
[/ACCOUNTING-FORMAT]`,
  tableForm: `[TABLE-FORM]
Table Title: ____________________

Column 1 | Column 2 | Column 3
__________ | __________ | __________
__________ | __________ | __________
__________ | __________ | __________
[/TABLE-FORM]`
};

function renderTAccountBlock(block) {
  const lines = block
    .replace(/\[\/?T-ACCOUNT\]/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(Boolean);

  const accountLine = lines.find(line => line.toLowerCase().startsWith("account title")) || "Account Title: ____________________";
  const rows = lines
    .filter(line => line.includes("|") && !line.toLowerCase().startsWith("debit | credit"))
    .map(line => line.split("|").map(cell => escapeHtml(cell.trim())));

  const normalRows = rows.filter(row => !row.join(" ").toLowerCase().includes("total debit") && !row.join(" ").toLowerCase().includes("total credit"));
  const totalRow = rows.find(row => row.join(" ").toLowerCase().includes("total debit") || row.join(" ").toLowerCase().includes("total credit"));
  const totalHtml = totalRow ? `<tr class="t-account-total-row"><td>${totalRow[0] || ""}</td><td>${totalRow[1] || ""}</td></tr>` : "";

  return `<div class="template-sheet t-account-template">
    <div class="t-account-title">${escapeHtml(accountLine.replace(/^Account Title:\s*/i, "") || "Account Title")}</div>
    <table class="t-account-table">
      <thead><tr><th>Debit</th><th>Credit</th></tr></thead>
      <tbody>
        ${normalRows.map(row => `<tr><td>${row[0] || ""}</td><td>${row[1] || ""}</td></tr>`).join("")}
        ${totalHtml}
      </tbody>
    </table>
  </div>`;
}

function renderAccountingFormatBlock(block) {
  const lines = block
    .replace(/\[\/?ACCOUNTING-FORMAT\]/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(Boolean);

  const metaRows = lines.filter(line => line.includes(":") && !line.includes("|"));
  const tableRows = lines
    .filter(line => line.includes("|") && !line.toLowerCase().startsWith("particulars | amount"))
    .map(line => line.split("|").map(cell => escapeHtml(cell.trim())));

  return `<div class="template-sheet accounting-format-template">
    <table class="template-table accounting-format-table">
      <tbody>
        ${metaRows.map(line => {
          const idx = line.indexOf(":");
          return `<tr><td>${escapeHtml(line.slice(0, idx))}</td><td>${escapeHtml(line.slice(idx + 1).trim())}</td></tr>`;
        }).join("")}
        <tr class="section-row"><th>Particulars</th><th>Amount</th></tr>
        ${tableRows.map(row => `<tr class="${(row[0] || "").toLowerCase().includes("final answer") ? "total-row" : ""}"><td>${row[0] || ""}</td><td>${row[1] || ""}</td></tr>`).join("")}
      </tbody>
    </table>
  </div>`;
}

function renderTableFormBlock(block) {
  const lines = block
    .replace(/\[\/?TABLE-FORM\]/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(Boolean);

  const titleLine = lines.find(line => line.toLowerCase().startsWith("table title:"));
  const rowLines = lines.filter(line => line.includes("|"));
  const header = rowLines[0] ? rowLines[0].split("|").map(cell => escapeHtml(cell.trim())) : ["Column 1", "Column 2"];
  const bodyRows = rowLines.slice(1).map(line => line.split("|").map(cell => escapeHtml(cell.trim())));

  return `<div class="template-sheet table-form-template">
    ${titleLine ? `<div class="table-form-title">${escapeHtml(titleLine.replace(/^Table Title:\s*/i, "") || "Table Form")}</div>` : ""}
    <table class="template-table table-form-table">
      <thead><tr>${header.map(cell => `<th>${cell}</th>`).join("")}</tr></thead>
      <tbody>
        ${bodyRows.map(row => `<tr>${header.map((_, i) => `<td>${row[i] || ""}</td>`).join("")}</tr>`).join("")}
      </tbody>
    </table>
  </div>`;
}

function renderDesignedTemplates(raw) {
  let output = escapeHtml(raw || "");
  output = output.replace(/\[T-ACCOUNT\][\s\S]*?\[\/T-ACCOUNT\]/g, match => renderTAccountBlock(match));
  output = output.replace(/\[ACCOUNTING-FORMAT\][\s\S]*?\[\/ACCOUNTING-FORMAT\]/g, match => renderAccountingFormatBlock(match));
  output = output.replace(/\[TABLE-FORM\][\s\S]*?\[\/TABLE-FORM\]/g, match => renderTableFormBlock(match));
  return output.replace(/\n/g, "<br>");
}

function insertTemplate(fieldId, templateKey) {
  const field = document.getElementById(fieldId);
  const template = accountingTemplates[templateKey];
  if (!field || !template) return;
  const spacer = field.value.trim() ? "\n\n" : "";
  field.value = `${field.value}${spacer}${template}`;
  field.focus();
}
function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + Number(days || 0));
  return d;
}

function makeTrial(days = 30) {
  const start = new Date();
  const end = addDays(start, days);
  return { trialStartDate: start.toISOString(), trialEndDate: end.toISOString(), trialDays: days };
}


function makeDefaultSubscriptions(type = "all", subjects = ["FAR"], months = 1) {
  const now = new Date();
  if (type === "all") {
    return { subscriptionType: "all_subjects", allSubjectsUntil: addMonths(now, months).toISOString(), subjectSubscriptions: {} };
  }
  const subjectSubscriptions = {};
  subjects.forEach(subject => { subjectSubscriptions[subject] = addMonths(now, months).toISOString(); });
  return { subscriptionType: "per_subject", allSubjectsUntil: "", subjectSubscriptions };
}

function getSubscriptionStatus(user) {
  return { active: true, accessibleSubjects: SUBJECTS.map(s => s.id), plan: "All subjects available" };
}

function hasSubjectAccess(subjectId, user = currentUser) {
  return true;
}

function activateLocalSubscription(userId, planType, subjects = [], months = 1) {
  const id = String(userId || "");
  let updated = null;
  for (const key of ["farDemoUsers", "farUsers"]) {
    const users = JSON.parse(localStorage.getItem(key) || "[]");
    const user = users.find(u => String(u.id || u.email) === id || String(u.email) === id);
    if (user && user.role === "student") {
      const now = new Date();
      user.subjectSubscriptions ||= {};
      if (planType === "all_subjects") {
        const base = user.allSubjectsUntil && new Date(user.allSubjectsUntil) > now ? new Date(user.allSubjectsUntil) : now;
        user.allSubjectsUntil = addMonths(base, months).toISOString();
        user.subscriptionType = "all_subjects";
      } else {
        const selected = subjects.length ? subjects : ["FAR"];
        selected.forEach(subject => {
          const existing = user.subjectSubscriptions[subject];
          const base = existing && new Date(existing) > now ? new Date(existing) : now;
          user.subjectSubscriptions[subject] = addMonths(base, months).toISOString();
        });
        user.subscriptionType = "per_subject";
      }
      localStorage.setItem(key, JSON.stringify(users));
      updated = user;
      if (currentUser && (currentUser.id === (user.id || user.email) || currentUser.email === user.email)) updateStoredCurrentUser({
        subscriptionType: user.subscriptionType,
        allSubjectsUntil: user.allSubjectsUntil,
        subjectSubscriptions: user.subjectSubscriptions
      });
    }
  }
  return updated;
}

function getLocalDemoUsers() {
  let users = JSON.parse(localStorage.getItem("farDemoUsers") || "null");
  if (!users) {
    users = [
      { id: "demo-admin", name: "Admin", contactNumber: "", email: "admin@example.com", password: "Admin123!", role: "admin", approvalStatus: "approved" },
      { id: "demo-student", name: "Student Demo", contactNumber: "09123456789", email: "student@example.com", password: "Student123!", role: "student", approvalStatus: "approved", quizCredits: 0, ...makeTrial(30), ...makeDefaultSubscriptions("all", [], 1) }
    ];
    localStorage.setItem("farDemoUsers", JSON.stringify(users));
  }
  return users;
}

function getTrialStatus(user) {
  if (!user || user.role === "admin") return { active: true, daysRemaining: null, message: "Admin account" };
  if (!user.trialEndDate) return { active: false, daysRemaining: 0, message: "No trial assigned" };
  const ms = new Date(user.trialEndDate).getTime() - Date.now();
  const daysRemaining = Math.max(0, Math.ceil(ms / (24 * 60 * 60 * 1000)));
  return {
    active: ms > 0,
    daysRemaining,
    message: ms > 0 ? `${daysRemaining} day(s) remaining` : "Trial expired"
  };
}

function isTrialActive() {
  return !currentUser || currentUser.role === "admin" || getTrialStatus(currentUser).active;
}

function isStrongPassword(password) {
  return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(password);
}

function getAuthHeaders() {
  const token = localStorage.getItem("farAuthToken");
  return token ? { "Authorization": `Bearer ${token}` } : {};
}

function setMessage(id, message, type = "") {
  const el = document.getElementById(id);
  if (!el) return;
  el.textContent = message;
  el.className = `form-message ${type}`;
}

function updateAuthUI() {
  document.body.classList.toggle("admin-session", currentUser?.role === "admin");
  document.body.classList.toggle("student-session", currentUser?.role === "student");
  const isLoggedIn = !!currentUser;
  document.querySelectorAll(".auth-only").forEach(el => el.classList.toggle("hidden-by-role", !isLoggedIn));
  document.querySelectorAll(".guest-only").forEach(el => el.classList.toggle("hidden-by-role", isLoggedIn));
  const isAdmin = isLoggedIn && currentUser.role === "admin";
  const isStudent = isLoggedIn && currentUser.role === "student";
  document.querySelectorAll(".admin-only, .admin-nav-only").forEach(el => el.classList.toggle("hidden-by-role", !isAdmin));
  document.querySelectorAll(".student-only, .student-nav-only").forEach(el => el.classList.toggle("hidden-by-role", !isStudent));
  const roleText = document.getElementById("currentRoleText");
  if (roleText && currentUser) roleText.textContent = `Logged in as ${currentUser.role}: ${currentUser.name ? currentUser.name + " | " : ""}${currentUser.email}`;
  const displayName = currentUser?.name || currentUser?.email || "Students";
  const homeWelcomeTitle = document.getElementById("homeWelcomeTitle");
  if (homeWelcomeTitle) {
    homeWelcomeTitle.textContent = currentUser?.role === "student" ? `Hi, ${displayName}` : (currentUser?.role === "admin" ? "Welcome, Admin!" : "Welcome, Students!");
  }
  const studentDashboardTitle = document.getElementById("studentDashboardTitle");
  if (studentDashboardTitle && currentUser?.role === "student") studentDashboardTitle.textContent = `Hi, ${displayName}`;
  const studentDashboardSubtitle = document.getElementById("studentDashboardSubtitle");
  if (studentDashboardSubtitle && currentUser?.role === "student") studentDashboardSubtitle.textContent = "Welcome to your student dashboard. Access lessons, take quizzes, and review your learning progress.";
  const trialText = document.getElementById("trialStatusText");
  const trialBanner = document.getElementById("trialBanner");
  if (trialText && currentUser) {
    const status = getTrialStatus(currentUser);
    if (currentUser.role === "student") {
      trialText.textContent = `Trial Status: ${status.message}. Trial ends on ${new Date(currentUser.trialEndDate).toLocaleDateString()}.`;
    } else {
      trialText.textContent = "Admin account: no trial limit.";
    }
  }
  if (trialBanner && currentUser?.role === "student") {
    const status = getTrialStatus(currentUser);
    trialBanner.textContent = status.active ? `Your access is active: ${status.message}.` : "Quiz credits are required for quizzes. You may request paid quiz credits at ₱2 per question.";
    trialBanner.className = `notice ${status.active ? "success" : "error"}`;
  }
  const quizCreditText = document.getElementById("quizCreditText");
  if (quizCreditText && currentUser?.role === "student") {
    quizCreditText.textContent = `Quiz Credits: ${Number(currentUser.quizCredits || 0)} item(s)`;
  }
  const quizAccessMessage = document.getElementById("quizAccessMessage");
  if (quizAccessMessage && currentUser?.role === "student") {
    quizAccessMessage.textContent = `Available approved quiz credits: ${Number(currentUser.quizCredits || 0)} item(s). Payment must be approved before generating quizzes.`;
    quizAccessMessage.className = Number(currentUser.quizCredits || 0) > 0 ? "notice success" : "notice error";
  }
  updatePaymentTotal();
  renderMyPaymentRequests();
}


async function sendRegistrationOtp(name, contactNumber, email, password) {
  if (!String(name || "").trim()) throw new Error("Student name is required.");
  if (!String(contactNumber || "").trim()) throw new Error("Contact number is required.");
  if (!email || !email.includes("@")) throw new Error("Valid email address is required.");
  if (!isStrongPassword(password)) throw new Error("Password must have at least 8 characters, uppercase, lowercase, and number.");

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/auth/send-registration-otp`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, contactNumber, email, password })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Unable to send OTP.");
    pendingRegistrationOtp = { name, contactNumber, email, password };
    return data;
  }

  throw new Error("Email OTP requires the Render backend. Please connect API_BASE_URL to your Render backend first.");
}

async function loginUser(email, password) {
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Login failed");
    localStorage.setItem("farAuthToken", data.token);
    return data.user;
  }
  const savedUsers = JSON.parse(localStorage.getItem("farUsers") || "[]");
  const user = [...getLocalDemoUsers(), ...savedUsers].find(u => u.email.toLowerCase() === email.toLowerCase() && u.password === password);
  if (!user) throw new Error("Invalid email or password");
  if (user.role === "student" && user.approvalStatus !== "approved") {
    throw new Error("Your account is still pending admin approval. Please wait for the admin to approve your registration.");
  }
  localStorage.setItem("farAuthToken", "local-demo-token");
  return { id: user.id || user.email, name: user.name || user.fullName || "", contactNumber: user.contactNumber || "", email: user.email, role: user.role, approvalStatus: user.approvalStatus || "approved", trialStartDate: user.trialStartDate, trialEndDate: user.trialEndDate, trialDays: user.trialDays, quizCredits: Number(user.quizCredits || 0), subscriptionType: user.subscriptionType || "per_subject", allSubjectsUntil: user.allSubjectsUntil || "", subjectSubscriptions: user.subjectSubscriptions || {} };
}

async function registerUser(name, contactNumber, email, password, otp, role = "student") {
  if (!String(name || "").trim()) throw new Error("Student name is required.");
  if (!String(contactNumber || "").trim()) throw new Error("Contact number is required.");
  if (!isStrongPassword(password)) throw new Error("Password must have at least 8 characters, uppercase, lowercase, and number.");
  role = "student";
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, contactNumber, email, password, otp, role })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Registration failed");
    return data.user;
  }
  if (!pendingRegistrationOtp || pendingRegistrationOtp.email.toLowerCase() !== email.toLowerCase()) throw new Error("Please request an OTP first.");
  if (Date.now() > pendingRegistrationOtp.expiresAt) throw new Error("OTP expired. Please request a new OTP.");
  if (String(otp || "").trim() !== pendingRegistrationOtp.otp) throw new Error("Invalid OTP.");
  const savedUsers = JSON.parse(localStorage.getItem("farUsers") || "[]");
  if ([...getLocalDemoUsers(), ...savedUsers].some(u => u.email.toLowerCase() === email.toLowerCase())) throw new Error("Email already exists.");
  savedUsers.push({
    id: crypto.randomUUID ? crypto.randomUUID() : email,
    name: String(name).trim(),
    contactNumber: String(contactNumber).trim(),
    email,
    password,
    role: "student",
    approvalStatus: "pending_approval",
    emailVerified: true,
    emailVerifiedAt: new Date().toISOString(),
    quizCredits: 0,
    ...makeTrial(30)
  });
  localStorage.setItem("farUsers", JSON.stringify(savedUsers));
  pendingRegistrationOtp = null;
  return savedUsers[savedUsers.length - 1];
}

function logoutUser() {
  currentUser = null;
  localStorage.removeItem("farCurrentUser");
  localStorage.removeItem("farAuthToken");
  updateAuthUI();
  showPage("login");
}

function requireLogin(pageId) {
  const protectedPages = ["student", "topics", "topic-detail", "quizzer", "quiz-taking", "quiz-result", "quiz-history", "about", "admin"];
  if (protectedPages.includes(pageId) && !currentUser) {
    showPage("login");
    return false;
  }
  if (pageId === "admin" && currentUser?.role !== "admin") {
    alert("Admin access only.");
    showPage("student");
    return false;
  }
  const trialProtectedPages = ["topics", "topic-detail"];
  if (currentUser?.role === "student" && trialProtectedPages.includes(pageId) && !isTrialActive()) {
    alert("Your trial has expired. Please contact the admin for access.");
    showPage("student");
    return false;
  }
  return true;
}

async function loadData() {
  if (API_BASE_URL) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/content`, { headers: getAuthHeaders() });
      if (!response.ok) throw new Error("Backend not available");
      const data = await response.json();
      topics = (data.topics.length ? data.topics : topics).map(ensureTopicShape);
      quizBank = data.quizBank.length ? data.quizBank : quizBank;
      initializeSubjectTopics();
      initializeQuestionSubjects();
      if (data.professorProfile) professorProfile = { ...professorProfile, ...data.professorProfile };
      if (data.siteSettings) siteSettings = { ...siteSettings, ...data.siteSettings };
      renderProfessorProfile();
      return;
    } catch (error) {
      console.warn("Using browser storage because backend is not reachable.", error);
    }
  }

  const savedTopics = localStorage.getItem("farTopics");
  const savedQuiz = localStorage.getItem("farQuizBank");
  const savedProfessorProfile = localStorage.getItem("farProfessorProfile");
  const savedSiteSettings = localStorage.getItem("farSiteSettings");
  if (savedTopics) topics = JSON.parse(savedTopics);
  if (savedQuiz) quizBank = JSON.parse(savedQuiz);
  if (savedProfessorProfile) professorProfile = { ...professorProfile, ...JSON.parse(savedProfessorProfile) };
  if (savedSiteSettings) siteSettings = { ...siteSettings, ...JSON.parse(savedSiteSettings) };
  topics = topics.map(ensureTopicShape);
  initializeSubjectTopics();
  initializeQuestionSubjects();

  quizBank = quizBank.map((q, index) => ({
    id: q.id || `local-q-${index + 1}-${Date.now()}`,
    reviewStatus: q.reviewStatus || "approved",
    adminNotes: q.adminNotes || "",
    ...q
  }));
  localStorage.setItem("farQuizBank", JSON.stringify(quizBank));
  renderProfessorProfile();
}

async function saveData() {
  localStorage.setItem("farTopics", JSON.stringify(topics));
  localStorage.setItem("farQuizBank", JSON.stringify(quizBank));
  localStorage.setItem("farProfessorProfile", JSON.stringify(professorProfile));
  localStorage.setItem("farSiteSettings", JSON.stringify(siteSettings));
}

function money(value) {
  return "₱" + Number(value).toLocaleString("en-PH", { maximumFractionDigits: 2 });
}

function shuffleArray(items) {
  const array = Array.isArray(items) ? [...items] : [];
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function roundMoney(value) {
  return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
}

function randomAmount(min, max, step = 10000) {
  return Math.floor((Math.random() * (max - min + step)) / step) * step + min;
}

function randomNumberFromRule(rule) {
  const min = Number(rule.min ?? 1);
  const max = Number(rule.max ?? 100);
  const step = Number(rule.step ?? 1);
  const raw = randomAmount(min, max, step);
  return Number(rule.decimals ? raw.toFixed(rule.decimals) : raw);
}

function defaultVariablesForFormula(formulaKey) {
  const defaults = {
    lowerCostNRV: {
      cost: { min: 80000, max: 250000, step: 10000, format: "money" },
      nrv: { min: 60000, max: 260000, step: 10000, format: "money" }
    },
    depreciation: {
      cost: { min: 200000, max: 800000, step: 50000, format: "money" },
      residual: { min: 10000, max: 80000, step: 5000, format: "money" },
      life: { min: 3, max: 8, step: 1, format: "number" }
    },
    debtCarryingAmount: {
      face: { min: 500000, max: 1500000, step: 50000, format: "money" },
      premiumDiscount: { min: 10000, max: 80000, step: 5000, format: "money" },
      amortization: { min: 5000, max: 30000, step: 1000, format: "money" }
    },
    custom: Object.fromEntries("ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(letter => [
      letter,
      { min: 10000, max: 500000, step: 10000, format: "money" }
    ]))
  };
  return defaults[formulaKey] || {};
}

function generateVariableValues(variables = {}) {
  const values = {};
  Object.entries(variables).forEach(([name, rule]) => {
    values[name] = randomNumberFromRule(rule || {});
  });
  return values;
}

function formatVariable(value, rule = {}) {
  return rule.format === "money" ? money(value) : Number(value).toLocaleString("en-PH");
}

function fillTemplate(template, values, variables = {}) {
  return String(template || "").replace(/\{(\w+)\}/g, (_, key) => {
    if (values[key] === undefined) return `{${key}}`;
    return formatVariable(values[key], variables[key]);
  });
}


function evaluateCustomExpression(expression, values) {
  if (!expression || typeof expression !== "string") {
    throw new Error("Custom formula expression is required.");
  }

  let safeExpression = expression.toUpperCase();
  const functions = {
    MIN: "Math.min",
    MAX: "Math.max",
    ROUND: "Math.round",
    ABS: "Math.abs",
    CEIL: "Math.ceil",
    FLOOR: "Math.floor"
  };

  Object.entries(functions).forEach(([name, replacement]) => {
    safeExpression = safeExpression.replace(new RegExp(`\\b${name}\\b`, "g"), replacement);
  });

  Object.entries(values).forEach(([name, value]) => {
    safeExpression = safeExpression.replace(new RegExp(`\\b${name.toUpperCase()}\\b`, "g"), String(Number(value)));
  });

  if (/[^0-9+\-*/().,\sMathminaxroundbsceilfloor]/i.test(safeExpression)) {
    throw new Error("Formula contains unsupported characters. Use variables A to Z, numbers, +, -, *, /, parentheses, MIN(), MAX(), ROUND(), ABS(), CEIL(), or FLOOR().");
  }

  const result = Function(`"use strict"; return (${safeExpression});`)();
  if (!Number.isFinite(Number(result))) {
    throw new Error("Formula result is not a valid number.");
  }
  return roundMoney(result);
}

function getAnswerFormat(variables = {}) {
  return Object.values(variables).some(rule => rule && rule.format === "money") ? "money" : "number";
}

function computeFormula(formulaKey, values, question = {}) {
  if (formulaKey === "custom") {
    try {
      const answer = evaluateCustomExpression(question.answerExpression, values);
      const answerFormat = getAnswerFormat(question.variables || {});
      return {
        answer,
        displayAnswer: answerFormat === "money" ? money(answer) : Number(answer).toLocaleString("en-PH"),
        solution: `Formula used: ${question.answerExpression}. Answer: ${answerFormat === "money" ? money(answer) : Number(answer).toLocaleString("en-PH")}.`
      };
    } catch (error) {
      return { answer: "", displayAnswer: "", solution: error.message };
    }
  }

  if (formulaKey === "lowerCostNRV") {
    const answer = Math.min(values.cost, values.nrv);
    return {
      answer,
      displayAnswer: money(answer),
      solution: `Compare cost ${money(values.cost)} and NRV ${money(values.nrv)}. The lower amount is ${money(answer)}. Therefore, inventory should be reported at ${money(answer)}.`
    };
  }

  if (formulaKey === "depreciation") {
    const answer = roundMoney((values.cost - values.residual) / values.life);
    return {
      answer,
      displayAnswer: money(answer),
      solution: `Annual depreciation = (${money(values.cost)} - ${money(values.residual)}) ÷ ${values.life} years = ${money(answer)}.`
    };
  }

  if (formulaKey === "debtCarryingAmount") {
    const answer = roundMoney(values.face + values.premiumDiscount - values.amortization);
    return {
      answer,
      displayAnswer: money(answer),
      solution: `Carrying amount = Face value ${money(values.face)} + unamortized premium/discount adjustment ${money(values.premiumDiscount)} - amortization ${money(values.amortization)} = ${money(answer)}.`
    };
  }

  return { answer: "", displayAnswer: "", solution: "No automated formula selected." };
}

function hydrateQuestion(question) {
  const q = JSON.parse(JSON.stringify(question));

  if (q.answerFormula) {
    const variableRules = q.variables && Object.keys(q.variables).length ? q.variables : defaultVariablesForFormula(q.answerFormula);
    const values = generateVariableValues(variableRules);
    const computed = computeFormula(q.answerFormula, values, q);

    q.generatedValues = values;
    q.question = fillTemplate(q.question, values, variableRules);
    q.answer = String(computed.answer);
    q.displayAnswer = computed.displayAnswer || String(computed.answer);
    q.explanation = q.solutionTemplate
      ? fillTemplate(q.solutionTemplate, { ...values, answer: computed.answer }, { ...variableRules, answer: { format: getAnswerFormat(variableRules) } })
      : computed.solution || q.explanation;
  }

  if (Array.isArray(q.choices) && q.choices.length > 1) {
    q.choices = shuffleArray(q.choices);
  }

  return q;
}

function showPage(pageId) {
  const requestedPageId = pageId;
  if (["home", "admin", "login"].includes(pageId) || (pageId === "student" && currentUser?.role !== "student")) {
    if (typeof clearSubjectTheme === "function") clearSubjectTheme();
  }
  // Role-aware Home behavior:
  // Guest Home = public landing page
  // Student Home = student dashboard
  // Admin Home = Admin Command Center / Dashboard Overview
  if (pageId === "home" && currentUser?.role === "student") pageId = "student";
  if (pageId === "home" && currentUser?.role === "admin") pageId = "admin";
  if (!requireLogin(pageId)) return;
  updateAuthUI();
  hideStudentHomePanelForPage(pageId);
  document.querySelectorAll(".page").forEach(page => page.classList.remove("active-page"));
  document.getElementById(pageId).classList.add("active-page");
  document.querySelectorAll(".nav-link").forEach(link => link.classList.remove("active"));
  const activeHref = requestedPageId === "home" ? "home" : pageId;
  document.querySelectorAll(`.nav-link[href="#${activeHref}"]`).forEach(link => link.classList.add("active"));
  if ((pageId === "home" || pageId === "student") && currentUser?.role === "student") {
    refreshCurrentUser().then(() => { updateAuthUI(); renderStudentHome(); });
  }
  if (pageId === "quizzer" && currentUser?.role === "student") {
    refreshCurrentUser().then(() => {
      updateAuthUI();
      updatePaymentTotal();
      renderMyPaymentRequests();
    });
  }
  if (pageId === "quiz-history" && currentUser?.role === "student") {
    renderQuizHistory();
  }
  if (pageId === "admin") {
    loadStudentsForAdmin();
    loadAdminQuizBank();
    loadProfessorEditor();
    loadStudentScores();
    renderAdminOverview();
    // When Admin clicks Home, always return to the Dashboard Overview.
    // This prevents the Home button from appearing "not clickable" when a previous Admin Menu section is still open.
    if (requestedPageId === "home" && typeof showAdminSection === "function") {
      showAdminSection("admin-overview");
    }
  }
  scrollToActivePage(pageId);
}

function renderTopics() {
  const grid = document.getElementById("topicsGrid");
  grid.innerHTML = topics.map(topic => {
    const intro = (topic.discussion || "Open this topic to view the available lesson menu tabs.").slice(0, 140);
    return `
      <article class="card">
        <h3>${escapeHtml(topic.title)}</h3>
        <p>${escapeHtml(intro)}${intro.length >= 140 ? "..." : ""}</p>
        <button class="btn primary" onclick="openTopic('${topic.id}')">Open Topic</button>
      </article>
    `;
  }).join("");
}

function renderQuizContent(value) {
  return renderAccountingContent(value);
}

function sanitizeLessonHtml(html) {
  let safe = String(html || "");
  safe = safe.replace(/<\/?(script|iframe|object|embed|link|style|meta|form|input|button|textarea|select)[^>]*>/gi, "");
  safe = safe.replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "");
  safe = safe.replace(/javascript:/gi, "");
  return safe;
}

function renderRichLessonContent(value) {
  const raw = String(value || "");
  if (raw.includes("[T-ACCOUNT]") || raw.includes("[ACCOUNTING-FORMAT]") || raw.includes("[TABLE-FORM]")) {
    return renderDesignedTemplates(raw);
  }
  const protectedHtml = raw
    .replace(/<\s*(strong|b)\s*>/gi, "[[BOLD_OPEN]]")
    .replace(/<\s*\/\s*(strong|b)\s*>/gi, "[[BOLD_CLOSE]]")
    .replace(/<\s*(em|i)\s*>/gi, "[[ITALIC_OPEN]]")
    .replace(/<\s*\/\s*(em|i)\s*>/gi, "[[ITALIC_CLOSE]]")
    .replace(/<\s*u\s*>/gi, "[[UNDERLINE_OPEN]]")
    .replace(/<\s*\/\s*u\s*>/gi, "[[UNDERLINE_CLOSE]]");
  return `<p>${escapeHtml(protectedHtml)
    .replace(/\n/g, "<br>")
    .replace(/\[\[BOLD_OPEN\]\]/g, "<strong>")
    .replace(/\[\[BOLD_CLOSE\]\]/g, "</strong>")
    .replace(/\[\[ITALIC_OPEN\]\]/g, "<em>")
    .replace(/\[\[ITALIC_CLOSE\]\]/g, "</em>")
    .replace(/\[\[UNDERLINE_OPEN\]\]/g, "<u>")
    .replace(/\[\[UNDERLINE_CLOSE\]\]/g, "</u>")}</p>`;
}

function formatTextareaSelection(textareaId, format) {
  const textarea = document.getElementById(textareaId);
  if (!textarea) return;
  const tags = { bold: ["<strong>", "</strong>"], italic: ["<em>", "</em>"], underline: ["<u>", "</u>"] };
  const [openTag, closeTag] = tags[format] || tags.bold;
  const start = textarea.selectionStart ?? textarea.value.length;
  const end = textarea.selectionEnd ?? textarea.value.length;
  const selected = textarea.value.slice(start, end) || "text";
  textarea.value = textarea.value.slice(0, start) + openTag + selected + closeTag + textarea.value.slice(end);
  textarea.focus();
  textarea.selectionStart = start + openTag.length;
  textarea.selectionEnd = start + openTag.length + selected.length;
}

function renderAccountingContent(value) {
  const raw = String(value || "");
  if (raw.includes("[T-ACCOUNT]") || raw.includes("[ACCOUNTING-FORMAT]") || raw.includes("[TABLE-FORM]")) {
    return renderDesignedTemplates(raw);
  }
  const escaped = escapeHtml(value || "").replace(/\n/g, "<br>");
  return `<p>${escaped}</p>`;
}

function openTopic(topicId, initialLessonId = null) {
  currentOpenTopicId = topicId;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const content = document.getElementById("topicContent");
  const customTabs = topic.tabs || [];
  const firstLessonId = customTabs[0]?.id || null;
  currentOpenLessonId = initialLessonId || firstLessonId;
  const menuItems = customTabs.map(tab => ({ id: tab.id, title: tab.title }));
  const menuButtons = menuItems.map(item => `
      <button type="button" class="lesson-menu-btn" data-lesson-id="${escapeHtml(item.id)}" onclick="showTopicLesson('${escapeJs(topic.id)}', '${escapeJs(item.id)}')">${escapeHtml(item.title)}</button>
    `).join("");

  content.innerHTML = `
    <aside class="topic-side">
      <h3>Lesson Menu</h3>
      <p class="muted-text small-note">Click one lesson tab to view its content.</p>
      ${menuButtons}
    </aside>
    <article class="topic-main">
      <h2>${escapeHtml(topic.title)}</h2>
      <div id="activeLessonContent" class="active-lesson-content"></div>
    </article>
  `;
  showPage("topic-detail");
  showTopicLesson(topic.id, currentOpenLessonId);
}

function showTopicLesson(topicId, lessonId) {
  currentOpenTopicId = topicId;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const holder = document.getElementById("activeLessonContent");
  if (!topic || !holder) return;

  const tabs = topic.tabs || [];
  const activeLessonId = lessonId || tabs[0]?.id || null;
  currentOpenLessonId = activeLessonId;

  if (!activeLessonId) {
    holder.innerHTML = `<section class="lesson-panel"><h3>No Lesson Menu Tabs Yet</h3><p class="muted-text">This topic has no Lesson Menu Tabs yet. Add tabs from Admin → Lesson Menu Tabs.</p></section>`;
    return;
  }

  const tab = tabs.find(item => item.id === activeLessonId);
  if (!tab) {
    holder.innerHTML = `<section class="lesson-panel"><h3>Lesson Not Found</h3><p class="muted-text">Please select another lesson tab.</p></section>`;
    return;
  }

  const subtabs = Array.isArray(tab.subtabs) ? tab.subtabs : [];
  const subButtons = subtabs.length ? `
    <div class="sublesson-menu">
      <h4>Sub-Lesson Menu</h4>
      <div class="sublesson-button-row">
        ${subtabs.map((sub, index) => `<button type="button" class="sublesson-btn" onclick="showSubLessonContent('${escapeJs(tab.id)}', '${escapeJs(sub.id)}')">${index + 1}. ${escapeHtml(sub.title)}</button>`).join("")}
      </div>
    </div>
    <div id="activeSubLessonContent" class="active-sublesson-content"></div>
  ` : "";

  markLessonViewed(topicId, activeLessonId);
  holder.innerHTML = `<section class="lesson-panel"><h3>${escapeHtml(tab.title)}</h3>${renderRichLessonContent(tab.content)}${subButtons}</section>`;
  document.querySelectorAll(".lesson-menu-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.lessonId === activeLessonId);
  });
  if (subtabs[0]) showSubLessonContent(tab.id, subtabs[0].id);
}

function showSubLessonContent(parentTabId, subTabId) {
  const topic = ensureTopicShape(topics.find(t => t.id === currentOpenTopicId));
  const parent = topic?.tabs?.find(tab => tab.id === parentTabId);
  const sub = parent?.subtabs?.find(item => item.id === subTabId);
  const holder = document.getElementById("activeSubLessonContent");
  if (!holder || !sub) return;
  holder.innerHTML = `<section class="sublesson-panel"><h4>${escapeHtml(sub.title)}</h4>${renderRichLessonContent(sub.content)}</section>`;
  document.querySelectorAll(".sublesson-btn").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("onclick")?.includes(`'${subTabId}'`));
  });
}


function populateSelects() {
  const topicOptions = topics.map(t => `<option value="${t.id}">${getSubjectShortName(t.subject)} - ${t.title}</option>`).join("");
  const quizTopicMenu = document.getElementById("quizTopicMenu");
  if (quizTopicMenu) {
    quizTopicMenu.innerHTML = `
      <label><input type="checkbox" name="quizTopicChoice" value="all" checked /> All Topics</label>
      ${topics.filter(t => currentUser?.role !== "student" || hasSubjectAccess(t.subject)).map(t => `<label><input type="checkbox" name="quizTopicChoice" value="${t.id}" /> ${escapeHtml(getSubjectShortName(t.subject) + " - " + t.title)}</label>`).join("")}
    `;
    setupQuizTopicCheckboxes();
    updateQuizTopicSummary();
  }
  document.getElementById("editTopicSelect").innerHTML = topicOptions;
  document.getElementById("newQuestionTopic").innerHTML = topicOptions;
  const lessonTabTopicSelect = document.getElementById("lessonTabTopicSelect");
  if (lessonTabTopicSelect) lessonTabTopicSelect.innerHTML = topicOptions;
  const reviewTopicFilter = document.getElementById("reviewTopicFilter");
  if (reviewTopicFilter) reviewTopicFilter.innerHTML = `<option value="all">All Topics</option>${topicOptions}`;
  populateAdminPdfTopicChoices();
  setupAdminPdfDifficultyCheckboxes();
  loadTopicEditor();
}

function loadTopicEditor() {
  const topicId = document.getElementById("editTopicSelect").value;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  if (!topic) return;
  document.getElementById("editTopicTitle").value = topic.title || "";
  document.getElementById("editDiscussion").value = topic.discussion || "";
  renderLessonTabsList();
}

function getSelectedLessonTabTopic() {
  const select = document.getElementById("lessonTabTopicSelect");
  const selectedId = select?.value || document.getElementById("editTopicSelect")?.value || topics[0]?.id;
  return ensureTopicShape(topics.find(t => t.id === selectedId));
}

function showLessonTabStatus(message, type = "info") {
  const status = document.getElementById("lessonTabStatus");
  if (!status) return;
  status.textContent = message || "";
  status.className = `inline-status ${type === "success" ? "status-success" : type === "error" ? "status-error" : "muted-text"}`;
}

function openSelectedLessonTopic() {
  const topic = getSelectedLessonTabTopic();
  if (!topic) return alert("Please select a topic first.");
  openTopic(topic.id);
}

function renderLessonTabsList() {
  const box = document.getElementById("lessonTabsList");
  const select = document.getElementById("lessonTabTopicSelect");
  if (!box || !select) return;
  const topic = getSelectedLessonTabTopic();
  if (!topic) {
    box.innerHTML = "<p class='muted-text'>No topic selected.</p>";
    showLessonTabStatus("No topic selected.");
    return;
  }
  if (select.value !== topic.id) select.value = topic.id;
  const tabs = topic.tabs || [];
  populateSubLessonParentSelect(topic);
  showLessonTabStatus(`${topic.title}: ${tabs.length} lesson menu tab(s) currently saved.`, tabs.length ? "success" : "info");

  box.innerHTML = `
    <div class="lesson-tab-list-header">
      <strong>${escapeHtml(getSubjectShortName(topic.subject))} - ${escapeHtml(topic.title)}</strong>
      <span>${tabs.length} tab(s)</span>
    </div>
    ${tabs.map(tab => {
      const preview = String(tab.content || "").replace(/\s+/g, " ").slice(0, 160);
      const updated = tab.updatedAt || tab.createdAt || "";
      return `
        <div class="lesson-tab-admin-card">
          <div class="lesson-tab-admin-main">
            <strong>${escapeHtml(tab.title)}</strong>
            <small>ID: ${escapeHtml(tab.id)}${updated ? ` • Last saved: ${new Date(updated).toLocaleString()}` : ""}</small>
            <p>${escapeHtml(preview || "No preview available.")}${preview.length >= 160 ? "..." : ""}</p>
            <div class="sublesson-admin-list">
              <strong>Sub-Lesson Tabs (${(tab.subtabs || []).length})</strong>
              ${(tab.subtabs || []).map(sub => `
                <div class="sublesson-admin-item">
                  <span>${escapeHtml(sub.title)}</span>
                  <div class="mini-actions">
                    <button class="btn ghost tiny-btn" onclick="startSubLessonEdit('${escapeJs(topic.id)}', '${escapeJs(tab.id)}', '${escapeJs(sub.id)}')">Edit</button>
                    <button class="btn danger-btn tiny-btn" onclick="deleteSubLessonTab('${escapeJs(topic.id)}', '${escapeJs(tab.id)}', '${escapeJs(sub.id)}')">Delete</button>
                  </div>
                </div>
              `).join("") || "<p class='muted-text small-note'>No sub-lessons yet.</p>"}
            </div>
          </div>
          <div class="mini-actions">
            <button class="btn ghost small-btn" onclick="prepareSubLessonForParent('${escapeJs(tab.id)}')">Add Sub-Tab</button>
            <button class="btn ghost small-btn" onclick="startLessonTabEdit('${escapeJs(topic.id)}', '${escapeJs(tab.id)}')">Edit</button>
            <button class="btn danger-btn small-btn" onclick="deleteLessonTab('${escapeJs(topic.id)}', '${escapeJs(tab.id)}')">Delete</button>
          </div>
        </div>
      `;
    }).join("") || "<p class='muted-text'>No additional lesson tabs yet. Add one above and it will appear here immediately.</p>"}
  `;
}

function populateSubLessonParentSelect(topic = null) {
  const select = document.getElementById("subLessonParentSelect");
  if (!select) return;
  const activeTopic = topic || getSelectedLessonTabTopic();
  const tabs = activeTopic?.tabs || [];
  const current = select.value;
  select.innerHTML = tabs.map(tab => `<option value="${escapeHtml(tab.id)}">${escapeHtml(tab.title)}</option>`).join("") || `<option value="">No lesson tabs available</option>`;
  if (tabs.some(tab => tab.id === current)) select.value = current;
}

function prepareSubLessonForParent(parentTabId) {
  const parentSelect = document.getElementById("subLessonParentSelect");
  if (parentSelect) parentSelect.value = parentTabId;
  cancelSubLessonEdit(false);
  document.getElementById("subLessonTabTitle")?.focus();
}

function cancelSubLessonEdit(clearParent = true) {
  document.getElementById("editingSubLessonParentId").value = "";
  document.getElementById("editingSubLessonId").value = "";
  document.getElementById("subLessonTabTitle").value = "";
  document.getElementById("subLessonTabContent").value = "";
  const button = document.getElementById("saveSubLessonTabButton");
  if (button) button.textContent = "Add Sub-Lesson Tab";
  if (clearParent) populateSubLessonParentSelect();
}

async function saveSubLessonTab() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topic = getSelectedLessonTabTopic();
  if (!topic) return alert("Please select a topic first.");
  const parentId = document.getElementById("editingSubLessonParentId").value || document.getElementById("subLessonParentSelect").value;
  const subId = document.getElementById("editingSubLessonId").value;
  const parent = topic.tabs.find(tab => tab.id === parentId);
  if (!parent) return alert("Please select a parent Lesson Menu Tab first.");
  parent.subtabs = Array.isArray(parent.subtabs) ? parent.subtabs : [];

  const title = document.getElementById("subLessonTabTitle").value.trim();
  const content = document.getElementById("subLessonTabContent").value.trim();
  if (!title || !content) return alert("Please enter sub-lesson title and content.");

  const original = JSON.parse(JSON.stringify(parent.subtabs));
  let savedSubId = subId;
  if (subId) {
    const sub = parent.subtabs.find(item => item.id === subId);
    if (!sub) return alert("Sub-lesson not found.");
    sub.title = title;
    sub.content = content;
    sub.updatedAt = new Date().toISOString();
  } else {
    savedSubId = slugify(title);
    if (parent.subtabs.some(item => item.id === savedSubId)) savedSubId = `${savedSubId}-${Date.now()}`;
    parent.subtabs.push({ id: savedSubId, title, content, createdAt: new Date().toISOString() });
  }

  try {
    if (API_BASE_URL) await updateLessonTabInBackend(topic.id, parent.id, { title: parent.title, content: parent.content, subtabs: parent.subtabs });
    await saveData();
    await refreshLessonViewAfterTabChange(topic.id, parent.id);
    cancelSubLessonEdit(false);
    showLessonTabStatus(subId ? "Sub-lesson tab updated." : "Sub-lesson tab added.", "success");
  } catch (error) {
    parent.subtabs = original;
    renderLessonTabsList();
    console.error(error);
    alert(error.message || "Sub-lesson tab was not saved.");
  }
}

function startSubLessonEdit(topicId, parentTabId, subTabId) {
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const parent = topic?.tabs?.find(tab => tab.id === parentTabId);
  const sub = parent?.subtabs?.find(item => item.id === subTabId);
  if (!topic || !parent || !sub) return alert("Sub-lesson not found.");
  const topicSelect = document.getElementById("lessonTabTopicSelect");
  if (topicSelect) topicSelect.value = topicId;
  populateSubLessonParentSelect(topic);
  document.getElementById("subLessonParentSelect").value = parentTabId;
  document.getElementById("editingSubLessonParentId").value = parentTabId;
  document.getElementById("editingSubLessonId").value = subTabId;
  document.getElementById("subLessonTabTitle").value = sub.title || "";
  document.getElementById("subLessonTabContent").value = sub.content || "";
  const button = document.getElementById("saveSubLessonTabButton");
  if (button) button.textContent = "Save Edited Sub-Lesson Tab";
  document.getElementById("subLessonTabTitle").focus();
}

async function deleteSubLessonTab(topicId, parentTabId, subTabId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const parent = topic?.tabs?.find(tab => tab.id === parentTabId);
  if (!topic || !parent) return alert("Sub-lesson not found.");
  if (!confirm("Delete this sub-lesson tab?")) return;
  const original = JSON.parse(JSON.stringify(parent.subtabs || []));
  parent.subtabs = (parent.subtabs || []).filter(item => item.id !== subTabId);
  try {
    if (API_BASE_URL) await updateLessonTabInBackend(topic.id, parent.id, { title: parent.title, content: parent.content, subtabs: parent.subtabs });
    await saveData();
    await refreshLessonViewAfterTabChange(topic.id, parent.id);
    showLessonTabStatus("Sub-lesson tab deleted.", "success");
  } catch (error) {
    parent.subtabs = original;
    renderLessonTabsList();
    console.error(error);
    alert(error.message || "Sub-lesson tab was not deleted.");
  }
}

async function saveTopicEdits() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topicId = document.getElementById("editTopicSelect").value;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  if (!topic) return alert("Topic not found.");

  topic.title = document.getElementById("editTopicTitle").value.trim();
  topic.discussion = document.getElementById("editDiscussion").value.trim();
  topic.standard = "";
  topic.summary = "";
  topic.formula = "";
  topic.computation = "";

  if (!topic.title || !topic.discussion) return alert("Topic title and discussion are required.");

  if (API_BASE_URL) {
    await fetch(`${API_BASE_URL}/api/topics/${topicId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(topic)
    });
  }

  await saveData();
  renderTopics();
  populateSelects();
  alert("Topic saved successfully.");
}

async function addTopic() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const title = document.getElementById("newTopicTitle").value.trim();
  const discussion = document.getElementById("newTopicDiscussion").value.trim();
  if (!title || !discussion) return alert("Please enter topic title and discussion.");

  let id = slugify(title);
  if (topics.some(t => t.id === id)) id = `${id}-${Date.now()}`;
  const newTopic = { id, title, standard: "", summary: "", discussion, formula: "", computation: "", tabs: [] };

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/topics`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(newTopic)
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add topic.");
    topics.push(data);
  } else {
    topics.push(newTopic);
  }

  await saveData();
  renderTopics();
  populateSelects();
  ["newTopicTitle", "newTopicDiscussion"].forEach(id => document.getElementById(id).value = "");
  alert("Topic added successfully.");
}

async function deleteTopic() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topicId = document.getElementById("editTopicSelect").value;
  const topic = topics.find(t => t.id === topicId);
  if (!topic) return alert("Topic not found.");
  const relatedQuestions = quizBank.filter(q => q.topic === topicId).length;
  const warning = relatedQuestions
    ? `Delete "${topic.title}" and ${relatedQuestions} related quiz question(s)? This cannot be undone.`
    : `Delete "${topic.title}"? This cannot be undone.`;
  if (!confirm(warning)) return;

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/topics/${topicId}`, {
      method: "DELETE",
      headers: getAuthHeaders()
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) return alert(data.error || "Unable to delete topic.");
  }

  topics = topics.filter(t => t.id !== topicId);
  quizBank = quizBank.filter(q => q.topic !== topicId);
  await saveData();
  renderTopics();
  populateSelects();
  renderAdminQuizReview();
  alert("Topic deleted successfully.");
}

async function refreshLessonViewAfterTabChange(topicId, preferredLessonId = null) {
  topics = topics.map(ensureTopicShape);
  initializeSubjectTopics();
  renderTopics();
  populateSelects();
  const topicSelect = document.getElementById("lessonTabTopicSelect");
  if (topicSelect && topicId) topicSelect.value = topicId;
  renderLessonTabsList();

  if (currentOpenTopicId === topicId || document.getElementById("topic-detail")?.classList.contains("active-page")) {
    const topic = ensureTopicShape(topics.find(t => t.id === topicId));
    if (topic) {
      const lessonToOpen = preferredLessonId && topic.tabs.some(tab => tab.id === preferredLessonId)
        ? preferredLessonId
        : (topic.tabs.some(tab => tab.id === currentOpenLessonId) ? currentOpenLessonId : topic.tabs[0]?.id || null);
      openTopic(topicId, lessonToOpen);
    }
  }
}

async function addLessonTab() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topicId = document.getElementById("lessonTabTopicSelect").value;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  if (!topic) return alert("Topic not found.");
  const title = document.getElementById("lessonTabTitle").value.trim();
  const content = document.getElementById("lessonTabContent").value.trim();
  if (!title || !content) return alert("Please enter tab title and content.");

  let id = slugify(title);
  if ((topic.tabs || []).some(tab => tab.id === id)) id = `${id}-${Date.now()}`;
  const newTab = { id, title, content, subtabs: [], createdAt: new Date().toISOString() };
  topic.tabs.push(newTab);

  try {
    if (API_BASE_URL) {
      const result = await createLessonTabInBackend(topic.id, newTab);
      if (result?.tab?.id) newTab.id = result.tab.id;
    }
    await saveData();
    document.getElementById("lessonTabTitle").value = "";
    document.getElementById("lessonTabContent").value = "";
    await refreshLessonViewAfterTabChange(topic.id, newTab.id);
    showLessonTabStatus(`Added lesson tab: ${newTab.title}`, "success");
    alert("Lesson tab added successfully and is now visible in the current tab list and actual lesson page.");
  } catch (error) {
    topic.tabs = topic.tabs.filter(tab => tab.id !== newTab.id);
    renderLessonTabsList();
    console.error(error);
    showLessonTabStatus(error.message || "Lesson tab was not saved.", "error");
    alert(error.message || "Lesson tab was not saved. Please check backend connection.");
  }
}

async function deleteLessonTab(topicId, tabId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  if (!topic) return alert("Topic not found.");
  if (!confirm("Delete this lesson tab?")) return;
  const originalTabs = [...topic.tabs];
  topic.tabs = topic.tabs.filter(tab => tab.id !== tabId);

  try {
    if (API_BASE_URL) await deleteLessonTabInBackend(topic.id, tabId);
    await saveData();
    await refreshLessonViewAfterTabChange(topic.id, topic.tabs[0]?.id || null);
    showLessonTabStatus("Lesson tab deleted. The current list and actual lesson page were refreshed.", "success");
    alert("Lesson tab deleted successfully and is no longer visible in the actual lesson page.");
  } catch (error) {
    topic.tabs = originalTabs;
    renderLessonTabsList();
    console.error(error);
    showLessonTabStatus(error.message || "Lesson tab was not deleted.", "error");
    alert(error.message || "Lesson tab was not deleted. Please check backend connection.");
  }
}

function startLessonTabEdit(topicId, tabId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const tab = topic?.tabs?.find(item => item.id === tabId);
  if (!topic || !tab) return alert("Lesson tab not found.");

  const topicSelect = document.getElementById("lessonTabTopicSelect");
  if (topicSelect) topicSelect.value = topicId;

  document.getElementById("editingLessonTabId").value = tabId;
  document.getElementById("editLessonTabTitle").value = tab.title || "";
  document.getElementById("editLessonTabContent").value = tab.content || "";
  document.getElementById("lessonTabEditPanel").classList.remove("hidden-panel");
  document.getElementById("editLessonTabTitle").focus();
}

function cancelLessonTabEdit() {
  document.getElementById("editingLessonTabId").value = "";
  document.getElementById("editLessonTabTitle").value = "";
  document.getElementById("editLessonTabContent").value = "";
  document.getElementById("lessonTabEditPanel").classList.add("hidden-panel");
}

async function saveLessonTabEdit() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topicId = document.getElementById("lessonTabTopicSelect").value;
  const tabId = document.getElementById("editingLessonTabId").value;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  const tab = topic?.tabs?.find(item => item.id === tabId);
  if (!topic || !tab) return alert("Lesson tab not found.");

  const newTitle = document.getElementById("editLessonTabTitle").value.trim();
  const newContent = document.getElementById("editLessonTabContent").value.trim();
  if (!newTitle || !newContent) return alert("Please enter tab title and content.");

  const original = { ...tab };
  tab.title = newTitle;
  tab.content = newContent;
  tab.updatedAt = new Date().toISOString();

  try {
    if (API_BASE_URL) await updateLessonTabInBackend(topic.id, tab.id, { title: newTitle, content: newContent });
    await saveData();
    await refreshLessonViewAfterTabChange(topic.id, tab.id);
    cancelLessonTabEdit();
    showLessonTabStatus(`Updated lesson tab: ${newTitle}`, "success");
    alert("Lesson tab updated successfully and is now visible in the current tab list and actual lesson page.");
  } catch (error) {
    Object.assign(tab, original);
    renderLessonTabsList();
    console.error(error);
    showLessonTabStatus(error.message || "Lesson tab was not updated.", "error");
    alert(error.message || "Lesson tab was not updated. Please check backend connection.");
  }
}

async function replaceLocalTopic(updatedTopic) {
  if (!updatedTopic) return null;
  const shaped = ensureTopicShape(updatedTopic);
  const index = topics.findIndex(item => item.id === shaped.id);
  if (index !== -1) topics[index] = shaped;
  return shaped;
}

async function saveTopicToBackend(topic) {
  if (!API_BASE_URL) return topic;
  const response = await fetch(`${API_BASE_URL}/api/topics/${topic.id}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getAuthHeaders() },
    body: JSON.stringify(ensureTopicShape(topic))
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || "Unable to save topic to backend.");
  }
  return replaceLocalTopic(data);
}

async function createLessonTabInBackend(topicId, tab) {
  if (!API_BASE_URL) return null;
  const response = await fetch(`${API_BASE_URL}/api/topics/${topicId}/tabs`, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...getAuthHeaders() },
    body: JSON.stringify(tab)
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Unable to add lesson tab to backend.");
  if (data.topic) await replaceLocalTopic(data.topic);
  return data;
}

async function updateLessonTabInBackend(topicId, tabId, values) {
  if (!API_BASE_URL) return null;
  const response = await fetch(`${API_BASE_URL}/api/topics/${topicId}/tabs/${tabId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getAuthHeaders() },
    body: JSON.stringify(values)
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Unable to update lesson tab in backend.");
  if (data.topic) await replaceLocalTopic(data.topic);
  return data;
}

async function deleteLessonTabInBackend(topicId, tabId) {
  if (!API_BASE_URL) return null;
  const response = await fetch(`${API_BASE_URL}/api/topics/${topicId}/tabs/${tabId}`, {
    method: "DELETE",
    headers: getAuthHeaders()
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Unable to delete lesson tab in backend.");
  if (data.topic) await replaceLocalTopic(data.topic);
  return data;
}

async function addQuizQuestion() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const topic = document.getElementById("newQuestionTopic").value;
  const type = document.getElementById("newQuestionType").value;
  const difficulty = document.getElementById("newQuestionDifficulty").value;
  const question = document.getElementById("newQuestionText").value.trim();
  const choicesRaw = document.getElementById("newQuestionChoices").value.trim();
  const answer = document.getElementById("newQuestionAnswer").value.trim();
  const answerFormula = document.getElementById("newQuestionFormula").value;
  const answerExpression = document.getElementById("newQuestionExpression")?.value.trim() || "";
  const variablesRaw = document.getElementById("newQuestionVariables").value.trim();
  const explanation = document.getElementById("newQuestionExplanation").value.trim();

  let variables = {};
  if (variablesRaw) {
    try {
      variables = JSON.parse(variablesRaw);
    } catch (error) {
      alert("Variable Settings must be valid JSON.");
      return;
    }
  }

  if (!question || !explanation || (!answerFormula && !answer)) {
    alert("Please complete the question, explanation, and either a manual answer or automated formula.");
    return;
  }

  if (answerFormula === "custom" && !answerExpression) {
    alert("Please enter a Custom Answer Formula Expression, such as A - B or MIN(A, B).");
    return;
  }

  const choices = choicesRaw ? choicesRaw.split("|").map(c => c.trim()).filter(Boolean) : [];
  const newQuestion = {
    id: crypto.randomUUID ? crypto.randomUUID() : `q-${Date.now()}`,
    topic,
    type,
    difficulty,
    question,
    choices,
    answer: answerFormula ? "" : answer,
    answerFormula: answerFormula || undefined,
    answerExpression: answerFormula === "custom" ? answerExpression : undefined,
    variables: answerFormula ? (Object.keys(variables).length ? variables : defaultVariablesForFormula(answerFormula)) : undefined,
    solutionTemplate: answerFormula ? explanation : undefined,
    explanation,
    reviewStatus: "pending_review",
    createdBy: currentUser.email,
    createdAt: new Date().toISOString()
  };

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/quizzes`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(newQuestion)
    });
    const savedQuestion = await response.json();
    quizBank.push(savedQuestion);
  } else {
    quizBank.push(newQuestion);
  }

  await saveData();
  alert("Question added successfully. It will appear in Admin Quiz Review.");
  document.getElementById("newQuestionText").value = "";
  document.getElementById("newQuestionChoices").value = "";
  document.getElementById("newQuestionAnswer").value = "";
  document.getElementById("newQuestionFormula").value = "";
  if (document.getElementById("newQuestionExpression")) document.getElementById("newQuestionExpression").value = "";
  document.getElementById("newQuestionVariables").value = "";
  document.getElementById("newQuestionExplanation").value = "";
  renderAdminQuizReview();
  if (document.getElementById("admin-question-repository")?.classList.contains("active-admin-section")) renderQuestionRepository();
}

function getTopicTitle(topicId) {
  return topics.find(t => t.id === topicId)?.title || topicId;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escapeJs(value) {
  return String(value ?? "")
    .replace(/\\/g, "\\\\")
    .replace(/'/g, "\\'")
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "");
}

function getFilteredAdminQuestions() {
  const topic = document.getElementById("reviewTopicFilter")?.value || "all";
  const type = document.getElementById("reviewTypeFilter")?.value || "all";
  const status = document.getElementById("reviewStatusFilter")?.value || "all";

  return quizBank.filter(q => {
    const topicMatch = topic === "all" || q.topic === topic;
    const typeMatch = type === "all" || q.type === type;
    const statusMatch = status === "all" || (q.reviewStatus || "approved") === status;
    return topicMatch && typeMatch && statusMatch;
  });
}

async function loadAdminQuizBank() {
  if (currentUser?.role !== "admin") return;
  if (API_BASE_URL) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/admin/quizzes`, { headers: getAuthHeaders() });
      if (response.ok) quizBank = await response.json();
    } catch (error) {
      console.warn("Unable to load admin quiz bank from backend.", error);
    }
  }
  renderAdminQuizReview();
}

function renderAdminQuizReview() {
  const box = document.getElementById("adminQuizList");
  if (!box) return;

  const questions = getFilteredAdminQuestions();
  const counts = quizBank.reduce((acc, q) => {
    const status = q.reviewStatus || "approved";
    acc.total += 1;
    acc[status] = (acc[status] || 0) + 1;
    acc.byTopic[q.topic] = acc.byTopic[q.topic] || { total: 0, approved: 0, pending_review: 0, needs_revision: 0 };
    acc.byTopic[q.topic].total += 1;
    acc.byTopic[q.topic][status] = (acc.byTopic[q.topic][status] || 0) + 1;
    return acc;
  }, { total: 0, approved: 0, pending_review: 0, needs_revision: 0, byTopic: {} });

  const summary = document.getElementById("quizReviewSummary");
  if (summary) {
    summary.innerHTML = `Total Questions: <strong>${counts.total}</strong> | Approved: <strong>${counts.approved || 0}</strong> | Pending Review: <strong>${counts.pending_review || 0}</strong> | Needs Revision: <strong>${counts.needs_revision || 0}</strong>`;
  }

  if (!questions.length) {
    box.innerHTML = "<p>No quiz questions found for the selected filter.</p>";
    return;
  }

  const currentSelected = document.getElementById("reviewQuestionPicker")?.value;
  const selectedId = questions.some(q => String(q.id) === String(currentSelected)) ? currentSelected : String(questions[0].id);

  const grouped = questions.reduce((acc, q) => {
    const key = q.topic || "uncategorized";
    if (!acc[key]) acc[key] = [];
    acc[key].push(q);
    return acc;
  }, {});

  const topicOrder = [
    ...topics.map(t => t.id),
    ...Object.keys(grouped).filter(topicId => !topics.some(t => t.id === topicId))
  ].filter(topicId => grouped[topicId]);

  const optionHtml = topicOrder.map(topicId => {
    const options = grouped[topicId].map((q, index) => {
      const status = (q.reviewStatus || "approved").replace(/_/g, " ");
      const difficulty = q.difficulty ? ` • ${q.difficulty}` : "";
      const typeLabel = q.type === "problem" ? "Problem" : "Theory";
      const label = `${index + 1}. ${typeLabel}${difficulty} • ${status} • ${getQuestionReviewLabel(q)}`;
      return `<option value="${escapeHtml(String(q.id))}" ${String(q.id) === String(selectedId) ? "selected" : ""}>${escapeHtml(label)}</option>`;
    }).join("");
    return `<optgroup label="${escapeHtml(getTopicTitle(topicId))}">${options}</optgroup>`;
  }).join("");

  box.innerHTML = `
    <div class="review-dropdown-panel">
      <label for="reviewQuestionPicker"><strong>Select Question to Review</strong></label>
      <select id="reviewQuestionPicker" class="review-question-select" onchange="renderSelectedReviewQuestion()">
        ${optionHtml}
      </select>
      <p class="muted-text">Use the dropdown to choose one question at a time. This avoids scrolling through the full question bank.</p>
    </div>
    <div id="selectedReviewQuestionCard" class="selected-review-wrapper"></div>
  `;

  renderSelectedReviewQuestion();
}

function getQuestionReviewLabel(q) {
  const raw = String(q.question || "Untitled question")
    .replace(/\[[^\]]+\]/g, "")
    .replace(/<[^>]*>/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return raw.length > 95 ? `${raw.slice(0, 95)}...` : raw;
}

function renderSelectedReviewQuestion() {
  const container = document.getElementById("selectedReviewQuestionCard");
  const picker = document.getElementById("reviewQuestionPicker");
  if (!container || !picker) return;

  const selectedId = picker.value;
  const questions = getFilteredAdminQuestions();
  const selectedQuestion = questions.find(q => String(q.id) === String(selectedId)) || questions[0];

  if (!selectedQuestion) {
    container.innerHTML = "<p>No question selected.</p>";
    return;
  }

  const topicQuestions = questions.filter(q => q.topic === selectedQuestion.topic);
  const topicCounts = topicQuestions.reduce((acc, q) => {
    const status = q.reviewStatus || "approved";
    acc.total += 1;
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, { total: 0, approved: 0, pending_review: 0, needs_revision: 0 });

  container.innerHTML = `
    <section class="topic-review-group selected-topic-review">
      <div class="topic-review-header">
        <div>
          <h4>${escapeHtml(getTopicTitle(selectedQuestion.topic || "uncategorized"))}</h4>
          <p>Only the selected question is shown below.</p>
        </div>
        <div class="topic-review-counts">
          <span>Total: ${topicCounts.total}</span>
          <span class="approved">Approved: ${topicCounts.approved || 0}</span>
          <span class="pending_review">Pending: ${topicCounts.pending_review || 0}</span>
          <span class="needs_revision">Revision: ${topicCounts.needs_revision || 0}</span>
        </div>
      </div>
      <div class="topic-review-cards">
        ${renderQuestionReviewCard(selectedQuestion, 0)}
      </div>
    </section>
  `;
}


function renderTopicReviewGroup(topicId, questions) {
  const topicCounts = questions.reduce((acc, q) => {
    const status = q.reviewStatus || "approved";
    acc.total += 1;
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, { total: 0, approved: 0, pending_review: 0, needs_revision: 0 });

  return `
    <section class="topic-review-group" id="review-topic-${escapeHtml(topicId)}">
      <div class="topic-review-header">
        <div>
          <h4>${escapeHtml(getTopicTitle(topicId))}</h4>
          <p>Review questions for this topic before students can use them.</p>
        </div>
        <div class="topic-review-counts">
          <span>Total: ${topicCounts.total}</span>
          <span class="approved">Approved: ${topicCounts.approved || 0}</span>
          <span class="pending_review">Pending: ${topicCounts.pending_review || 0}</span>
          <span class="needs_revision">Revision: ${topicCounts.needs_revision || 0}</span>
        </div>
      </div>
      <div class="topic-review-cards">
        ${questions.map((q, index) => renderQuestionReviewCard(q, index)).join("")}
      </div>
    </section>`;
}

function renderQuestionReviewCard(q, index) {
  const qid = q.id || `question-${index}`;
  const status = q.reviewStatus || "approved";
  const choices = Array.isArray(q.choices) && q.choices.length ? q.choices.join(" | ") : "";
  const answerValue = q.answerFormula ? `[Auto: ${q.answerFormula}${q.answerExpression ? ` = ${q.answerExpression}` : ""}]` : (q.answer || "");
  const variablesValue = q.variables ? JSON.stringify(q.variables, null, 2) : "";
  return `
    <article class="quiz-review-card">
      <div class="quiz-review-head">
        <div>
          <span class="tag">${escapeHtml(q.type === "problem" ? "Problem Solving" : "Theory")}</span>
          <span class="status-badge ${status}">${escapeHtml(status.replace(/_/g, " "))}</span>
        </div>
        <small>${escapeHtml(q.difficulty || "")}</small>
      </div>

      <label>Question</label>
      <textarea id="review-question-${qid}" rows="3">${escapeHtml(q.question)}</textarea>

      <label>Choices separated by |</label>
      <input id="review-choices-${qid}" value="${escapeHtml(choices)}" placeholder="Leave blank for no choices" />

      <div class="review-two-col">
        <div>
          <label>Correct Answer / Formula</label>
          <input id="review-answer-${qid}" value="${escapeHtml(answerValue)}" ${q.answerFormula ? "disabled" : ""} />
        </div>
        <div>
          <label>Admin Notes</label>
          <input id="review-notes-${qid}" value="${escapeHtml(q.adminNotes || "")}" placeholder="Optional note" />
        </div>
      </div>

      ${q.answerFormula ? `
        <div class="review-two-col">
          <div>
            <label>Formula Key</label>
            <input id="review-formula-${qid}" value="${escapeHtml(q.answerFormula || "")}" placeholder="custom, lowerCostNRV, depreciation, debtCarryingAmount" />
          </div>
          <div>
            <label>Custom Expression</label>
            <input id="review-expression-${qid}" value="${escapeHtml(q.answerExpression || "")}" placeholder="Example: A - B or MIN(A, B)" />
          </div>
        </div>
        <label>Variable Settings JSON</label>
        <textarea id="review-variables-${qid}" rows="5">${escapeHtml(variablesValue)}</textarea>
      ` : ""}

      <label>Explanation / Solution Template</label>
      <textarea id="review-explanation-${qid}" rows="3">${escapeHtml(q.solutionTemplate || q.explanation)}</textarea>

      <div class="quiz-review-actions">
        <button class="btn primary" onclick="saveReviewedQuestion('${qid}')">Save Edits</button>
        <button class="btn secondary" onclick="setQuestionStatus('${qid}', 'approved')">Approve</button>
        <button class="btn ghost" onclick="setQuestionStatus('${qid}', 'needs_revision')">Needs Revision</button>
        <button class="btn danger-btn" onclick="deleteQuestion('${qid}')">Delete</button>
      </div>
    </article>`;
}

async function saveReviewedQuestion(questionId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const question = quizBank.find(q => q.id === questionId);
  if (!question) return alert("Question not found.");

  const choicesRaw = document.getElementById(`review-choices-${questionId}`).value.trim();
  const explanationValue = document.getElementById(`review-explanation-${questionId}`).value.trim();
  const updated = {
    ...question,
    question: document.getElementById(`review-question-${questionId}`).value.trim(),
    choices: choicesRaw ? choicesRaw.split("|").map(c => c.trim()).filter(Boolean) : [],
    explanation: explanationValue,
    adminNotes: document.getElementById(`review-notes-${questionId}`).value.trim(),
    updatedAt: new Date().toISOString()
  };

  if (question.answerFormula) {
    updated.answerFormula = document.getElementById(`review-formula-${questionId}`).value.trim();
    updated.answerExpression = document.getElementById(`review-expression-${questionId}`)?.value.trim() || undefined;
    updated.solutionTemplate = explanationValue;
    if (updated.answerFormula === "custom" && !updated.answerExpression) {
      alert("Custom formula questions need an expression, such as A - B or MIN(A, B).");
      return;
    }
    const variablesRaw = document.getElementById(`review-variables-${questionId}`).value.trim();
    try {
      updated.variables = variablesRaw ? JSON.parse(variablesRaw) : defaultVariablesForFormula(updated.answerFormula);
    } catch (error) {
      alert("Variable Settings must be valid JSON.");
      return;
    }
  } else {
    updated.answer = document.getElementById(`review-answer-${questionId}`).value.trim();
  }

  if (!updated.question || !updated.explanation || (!updated.answerFormula && !updated.answer)) {
    alert("Question, correct answer/formula, and explanation are required.");
    return;
  }

  await persistQuestionUpdate(questionId, updated);
  alert("Question edits saved.");
}

async function setQuestionStatus(questionId, status) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const question = quizBank.find(q => q.id === questionId);
  if (!question) return alert("Question not found.");
  const updated = { ...question, reviewStatus: status, reviewedBy: currentUser.email, reviewedAt: new Date().toISOString() };
  await persistQuestionUpdate(questionId, updated);
}

async function persistQuestionUpdate(questionId, updatedQuestion) {
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/quizzes/${questionId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(updatedQuestion)
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to update question.");
    quizBank = quizBank.map(q => q.id === questionId ? data : q);
  } else {
    quizBank = quizBank.map(q => q.id === questionId ? updatedQuestion : q);
  }
  await saveData();
  renderAdminQuizReview();
}

async function deleteQuestion(questionId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (!confirm("Delete this quiz question?")) return;

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/quizzes/${questionId}`, {
      method: "DELETE",
      headers: getAuthHeaders()
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to delete question.");
  }

  quizBank = quizBank.filter(q => q.id !== questionId);
  await saveData();
  renderAdminQuizReview();
}


function getLocalPaymentRequests() {
  return JSON.parse(localStorage.getItem("farPaymentRequests") || "[]");
}

function saveLocalPaymentRequests(requests) {
  localStorage.setItem("farPaymentRequests", JSON.stringify(requests));
}



function getLocalCreditTransactions() {
  return JSON.parse(localStorage.getItem("farCreditTransactions") || "[]");
}

function saveLocalCreditTransactions(transactions) {
  localStorage.setItem("farCreditTransactions", JSON.stringify(transactions));
}

function findLocalUserByIdOrEmail(userId, email) {
  const wantedId = String(userId || "").toLowerCase();
  const wantedEmail = String(email || "").toLowerCase();
  for (const key of ["farDemoUsers", "farUsers"]) {
    const users = JSON.parse(localStorage.getItem(key) || "[]");
    const user = users.find(u => String(u.id || "").toLowerCase() === wantedId || String(u.email || "").toLowerCase() === wantedEmail);
    if (user) return { key, users, user };
  }
  return null;
}

function syncLocalPaymentCredits(req) {
  if (!req) return { added: 0, message: "Payment request not found." };
  const transactions = getLocalCreditTransactions();
  const existing = transactions.find(t => t.paymentRequestId === req.id);
  const requestedCredits = Math.max(1, Number(req.itemCount || req.creditsAdded || 0));
  const found = findLocalUserByIdOrEmail(req.userId, req.email);
  if (!found) return { added: 0, message: "Student account was not found for this payment request." };

  if (existing) {
    req.creditsApplied = Number(existing.credits || req.creditsApplied || 0);
    req.creditsAdded = requestedCredits;
    req.creditSyncedAt = new Date().toISOString();
    req.linkedUserId = found.user.id || found.user.email;
    return { added: 0, user: found.user, message: `Credits were already applied for this payment request. Current credits: ${Number(found.user.quizCredits || 0)}.` };
  }

  found.user.quizCredits = Math.max(0, Number(found.user.quizCredits || 0) + requestedCredits);
  localStorage.setItem(found.key, JSON.stringify(found.users));
  transactions.push({
    id: crypto.randomUUID ? crypto.randomUUID() : `credit-${Date.now()}`,
    paymentRequestId: req.id,
    userId: found.user.id || found.user.email,
    email: found.user.email,
    credits: requestedCredits,
    createdAt: new Date().toISOString(),
    createdBy: currentUser?.email || "admin"
  });
  saveLocalCreditTransactions(transactions);
  req.creditsAdded = requestedCredits;
  req.creditsApplied = requestedCredits;
  req.creditSyncedAt = new Date().toISOString();
  req.linkedUserId = found.user.id || found.user.email;
  if (currentUser && (currentUser.id === (found.user.id || found.user.email) || currentUser.email === found.user.email)) {
    updateStoredCurrentUser({ quizCredits: found.user.quizCredits });
  }
  return { added: requestedCredits, user: found.user, message: `${requestedCredits} quiz credit(s) added. Current credits: ${Number(found.user.quizCredits || 0)}.` };
}

function togglePaymentPanel() {
  const panel = document.getElementById("paymentPanel");
  if (panel) panel.classList.toggle("hidden-panel");
  updatePaymentTotal();
  renderMyPaymentRequests();
}

function updatePaymentTotal() {
  const input = document.getElementById("paymentItemCount");
  const totalText = document.getElementById("paymentTotalText");
  if (!input || !totalText) return;
  const items = Math.max(1, Number(input.value || 1));
  const total = items * QUIZ_PRICE_PER_ITEM;
  totalText.textContent = `Total: ₱${total.toLocaleString()}`;
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    if (!file) return resolve("");
    if (!/^image\/(jpeg|jpg|png)$/i.test(file.type)) return reject(new Error("Receipt must be JPG, JPEG, or PNG."));
    if (file.size > 2 * 1024 * 1024) return reject(new Error("Receipt screenshot must be 2MB or smaller."));
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("Unable to read receipt screenshot."));
    reader.readAsDataURL(file);
  });
}

async function submitPaymentRequest() {
  if (!currentUser || currentUser.role !== "student") return alert("Student login is required.");
  const itemCount = Math.max(1, Number(document.getElementById("paymentItemCount")?.value || 1));
  const planType = "quiz_credits";
  const subject = document.getElementById("subjectFilter")?.value || "FAR";
  const months = 1;
  const reference = document.getElementById("paymentReference")?.value.trim() || "";
  const receiptFile = document.getElementById("paymentReceipt")?.files?.[0] || null;
  const amount = itemCount * QUIZ_PRICE_PER_ITEM;

  try {
    const receiptData = await fileToDataUrl(receiptFile);
    const receiptFileName = receiptFile?.name || "";
    if (!reference && !receiptData) throw new Error("Please enter a GCash reference number or upload a receipt screenshot.");

    if (API_BASE_URL) {
      const response = await fetch(`${API_BASE_URL}/api/payments/request`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ itemCount, reference, receiptData, receiptFileName, planType, subject, months, amount })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Unable to submit payment request.");
    } else {
      const requests = getLocalPaymentRequests();
      requests.push({
        id: crypto.randomUUID ? crypto.randomUUID() : `pay-${Date.now()}`,
        userId: currentUser.id || currentUser.email,
        name: currentUser.name || "",
        email: currentUser.email,
        itemCount,
        planType,
        subject,
        months,
        amount,
        reference,
        receiptData,
        receiptFileName,
        status: "pending_payment",
        createdAt: new Date().toISOString()
      });
      saveLocalPaymentRequests(requests);
    }
    if (document.getElementById("paymentReference")) document.getElementById("paymentReference").value = "";
    if (document.getElementById("paymentReceipt")) document.getElementById("paymentReceipt").value = "";
    setMessage("paymentRequestMessage", `Payment request submitted for ${itemCount} quiz credit(s), total ₱${amount.toLocaleString()}. Please wait for admin approval before generating a quiz.`, "success");
    renderMyPaymentRequests();
  } catch (error) {
    setMessage("paymentRequestMessage", error.message, "error");
  }
}

async function renderMyPaymentRequests() {
  const box = document.getElementById("myPaymentRequests");
  if (!box || !currentUser || currentUser.role !== "student") return;
  if (API_BASE_URL) {
    box.innerHTML = `<p class="muted-text">Your submitted requests will be validated by the admin. Once approved, quiz credits will be added to your account.</p>`;
    return;
  }
  const requests = getLocalPaymentRequests().filter(r => r.email === currentUser.email);
  box.innerHTML = requests.slice().reverse().map(r => `
    <div class="payment-row">
      <div><strong>${r.itemCount} quiz credit(s)</strong> • ₱${Number(r.amount || 0).toLocaleString()}<br><small>${new Date(r.createdAt).toLocaleString()} | Ref: ${escapeHtml(r.reference || "No reference")} ${r.receiptData ? "| Receipt uploaded" : ""}</small></div>
      <span class="status-pill ${r.status}">${String(r.status).replace(/_/g, " ")}</span>
    </div>
  `).join("") || `<p class="muted-text">No payment requests yet.</p>`;
}

function updateStoredCurrentUser(updatedUser) {
  currentUser = { ...currentUser, ...updatedUser };
  localStorage.setItem("farCurrentUser", JSON.stringify(currentUser));
  updateAuthUI();
}

async function refreshCurrentUser() {
  if (!currentUser) return null;
  if (API_BASE_URL) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/me`, { headers: getAuthHeaders() });
      const data = await response.json();
      if (response.ok) {
        updateStoredCurrentUser(data);
        return currentUser;
      }
    } catch (error) {
      console.warn("Unable to refresh user account.", error);
    }
    return currentUser;
  }

  const users = [...getLocalDemoUsers(), ...JSON.parse(localStorage.getItem("farUsers") || "[]")];
  const fresh = users.find(u => (u.id || u.email) === (currentUser.id || currentUser.email) || u.email === currentUser.email);
  if (fresh) updateStoredCurrentUser({
    name: fresh.name || fresh.fullName || currentUser.name,
    contactNumber: fresh.contactNumber || currentUser.contactNumber,
    approvalStatus: fresh.approvalStatus || currentUser.approvalStatus,
    trialStartDate: fresh.trialStartDate,
    trialEndDate: fresh.trialEndDate,
    trialDays: fresh.trialDays,
    quizCredits: Number(fresh.quizCredits || 0),
    subscriptionType: fresh.subscriptionType,
    allSubjectsUntil: fresh.allSubjectsUntil,
    subjectSubscriptions: fresh.subjectSubscriptions || {}
  });
  return currentUser;
}

function updateLocalUserCredits(userId, delta) {
  const targetId = String(userId || "").trim();
  if (!targetId) return null;

  for (const key of ["farDemoUsers", "farUsers"]) {
    const users = JSON.parse(localStorage.getItem(key) || "[]");

    // IMPORTANT: match only the selected student.
    // Do not fall back to currentUser.email because the admin is the logged-in user
    // when adding credits manually, which caused credits to be added to the admin account.
    const user = users.find(u => String(u.id || u.email) === targetId || String(u.email) === targetId);

    if (user) {
      if (user.role !== "student") {
        alert("Quiz credits can only be added to student accounts.");
        return null;
      }

      user.quizCredits = Math.max(0, Number(user.quizCredits || 0) + Number(delta || 0));
      localStorage.setItem(key, JSON.stringify(users));

      if (currentUser && currentUser.role === "student" && (currentUser.id === (user.id || user.email) || currentUser.email === user.email)) {
        updateStoredCurrentUser({ quizCredits: user.quizCredits });
      }
      return user;
    }
  }
  return null;
}

async function consumeQuizCredits(itemCount) {
  if (currentUser?.role !== "student") return true;
  if (Number(currentUser.quizCredits || 0) < itemCount) return false;
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/me/use-quiz-credits`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ itemCount })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Unable to use quiz credits.");
    updateStoredCurrentUser(data.user || data);
  } else {
    updateLocalUserCredits(currentUser.id || currentUser.email, -itemCount);
  }
  return true;
}

async function loadPaymentRequestsForAdmin() {
  const box = document.getElementById("adminPaymentRequests");
  if (!box || currentUser?.role !== "admin") return;
  let requests = [];
  try {
    if (API_BASE_URL) {
      const response = await fetch(`${API_BASE_URL}/api/admin/payment-requests`, { headers: getAuthHeaders() });
      requests = await response.json();
      if (!response.ok) throw new Error(requests.error || "Unable to load payment requests.");
    } else {
      requests = getLocalPaymentRequests();
    }
    box.innerHTML = requests.slice().reverse().map(r => `
      <div class="student-row payment-admin-row">
        <div>
          <strong>${escapeHtml(r.name || r.email || "Student")}</strong><br />
          <small>${escapeHtml(r.email || "")} | ${r.itemCount} item(s) × ₱${QUIZ_PRICE_PER_ITEM} = ₱${Number(r.amount || 0).toLocaleString()}</small><br />
          <small>Reference: ${escapeHtml(r.reference || "No reference")} | ${new Date(r.createdAt || Date.now()).toLocaleString()}</small><br />
          ${r.receiptData ? `<a href="${r.receiptData}" target="_blank" rel="noopener">View Receipt Screenshot</a>` : `<small>No receipt screenshot uploaded</small>`}
        </div>
        <div class="trial-actions">
          <span class="status-pill ${r.status}">${String(r.status || "pending_payment").replace(/_/g, " ")}</span>
          ${r.status === "pending_payment" ? `<button class="btn secondary" onclick="approvePaymentRequest('${r.id}')">Approve Payment / Activate Access</button><button class="btn danger-btn" onclick="rejectPaymentRequest('${r.id}')">Reject</button>` : `<small>Credits added: ${Number(r.creditsAdded || r.itemCount || 0)}</small>${r.status === "paid_approved" ? `<button class="btn light-btn" onclick="reapplyApprovedPaymentCredits('${r.id}')">Re-check / Add Missing Credits</button>` : ""}`}
        </div>
      </div>
    `).join("") || `<p>No payment requests found.</p>`;
  } catch (error) {
    box.innerHTML = `<p class="form-message error">${escapeHtml(error.message)}</p>`;
  }
}

async function approvePaymentRequest(requestId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (!confirm("Approve this payment? The system will automatically add quiz credits equal to the student's requested number of items.")) return;
  let approvalMessage = "Payment approved. Quiz credits were automatically added based on the student's request.";
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/payment-requests/${requestId}/approve`, { method: "POST", headers: getAuthHeaders() });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to approve payment.");
    approvalMessage = data.message || approvalMessage;
  } else {
    const requests = getLocalPaymentRequests();
    const req = requests.find(r => r.id === requestId);
    if (!req) return alert("Payment request not found.");
    req.status = "paid_approved";
    req.approvedAt = new Date().toISOString();
    req.approvedBy = currentUser.email;
    const sync = syncLocalPaymentCredits(req);
    saveLocalPaymentRequests(requests);
    approvalMessage = sync.message || `${Number(req.itemCount || 0)} quiz credit(s) automatically added to ${req.name || req.email}.`;
  }
  await loadPaymentRequestsForAdmin();
  alert(approvalMessage);
}


async function reapplyApprovedPaymentCredits(requestId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (!confirm("Re-check this approved payment and add any missing quiz credits? Use this if the student did not receive credits after approval.")) return;
  let message = "Credit check completed.";
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/payment-requests/${requestId}/reapply-credits`, { method: "POST", headers: getAuthHeaders() });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to re-check credits.");
    message = data.message || message;
  } else {
    const requests = getLocalPaymentRequests();
    const req = requests.find(r => r.id === requestId);
    if (!req) return alert("Payment request not found.");
    if (req.status !== "paid_approved") return alert("Only approved payments can be re-checked.");
    const sync = syncLocalPaymentCredits(req);
    saveLocalPaymentRequests(requests);
    message = sync.message || "Credit check completed.";
  }
  await loadPaymentRequestsForAdmin();
  alert(message);
}

function findLocalUserByPaymentRequest(req) {
  const users = [...getLocalDemoUsers(), ...JSON.parse(localStorage.getItem("farUsers") || "[]")];
  return users.find(u => (req.userId && (u.id || u.email) === req.userId) || (u.email || "").toLowerCase() === String(req.email || "").toLowerCase());
}

async function rejectPaymentRequest(requestId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (!confirm("Reject this payment request?")) return;
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/payment-requests/${requestId}/reject`, { method: "POST", headers: getAuthHeaders() });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to reject payment.");
  } else {
    const requests = getLocalPaymentRequests();
    const req = requests.find(r => r.id === requestId);
    if (req) req.status = "rejected";
    saveLocalPaymentRequests(requests);
  }
  await loadPaymentRequestsForAdmin();
}

function toggleQuizTopicDropdown() {
  const menu = document.getElementById("quizTopicMenu");
  if (menu) menu.classList.toggle("hidden-panel");
}

function getSelectedQuizTopics() {
  const checked = Array.from(document.querySelectorAll('input[name="quizTopicChoice"]:checked')).map(input => input.value);
  return checked.length ? checked : ["all"];
}

function updateQuizTopicSummary() {
  const summary = document.getElementById("quizTopicSummary");
  if (!summary) return;
  const selected = getSelectedQuizTopics();
  if (selected.includes("all") || selected.length === 0) {
    summary.textContent = "All Topics";
    return;
  }
  const names = selected.map(id => topics.find(t => t.id === id)?.title || id);
  summary.textContent = names.length <= 2 ? names.join(", ") : `${names.length} topics selected`;
}

function setupQuizTopicCheckboxes() {
  const boxes = Array.from(document.querySelectorAll('input[name="quizTopicChoice"]'));
  const allBox = boxes.find(box => box.value === "all");
  if (!boxes.length || !allBox) return;

  boxes.forEach(box => {
    box.onchange = () => {
      if (box.value === "all" && box.checked) {
        boxes.filter(item => item.value !== "all").forEach(item => { item.checked = false; });
      } else if (box.value !== "all" && box.checked) {
        allBox.checked = false;
      }

      const anyChecked = boxes.some(item => item.checked);
      if (!anyChecked) allBox.checked = true;
      updateQuizTopicSummary();
    };
  });
}

function getSelectedQuizDifficulties() {
  const checked = Array.from(document.querySelectorAll('input[name="quizDifficulty"]:checked')).map(input => input.value);
  return checked.length ? checked : ["all"];
}

function setupDifficultyCheckboxes() {
  const boxes = Array.from(document.querySelectorAll('input[name="quizDifficulty"]'));
  const allBox = boxes.find(box => box.value === "all");
  if (!boxes.length || !allBox) return;

  boxes.forEach(box => {
    box.addEventListener("change", () => {
      if (box.value === "all" && box.checked) {
        boxes.filter(item => item.value !== "all").forEach(item => { item.checked = false; });
      } else if (box.value !== "all" && box.checked) {
        allBox.checked = false;
      }

      const anyChecked = boxes.some(item => item.checked);
      if (!anyChecked) allBox.checked = true;
    });
  });
}


function getNumberValue(id) {
  const el = document.getElementById(id);
  return Math.max(0, Number(el?.value || 0));
}

function updateAdvancedQuizTotals() {
  const typeTotal = getNumberValue("theoryItemCount") + getNumberValue("problemItemCount");
  const diffTotal = getNumberValue("easyItemCount") + getNumberValue("mediumItemCount") + getNumberValue("hardItemCount");
  const total = Math.max(typeTotal, diffTotal);
  const totalBox = document.getElementById("advancedTotalItems");
  const creditBox = document.getElementById("advancedRequiredCredits");
  const paymentItems = document.getElementById("paymentItemCount");
  if (totalBox) totalBox.textContent = total;
  if (creditBox) creditBox.textContent = total;
  if (paymentItems && total > 0) {
    paymentItems.value = total;
    if (typeof updatePaymentTotal === "function") updatePaymentTotal();
  }
  const notice = document.getElementById("quizAccessMessage");
  if (notice && typeTotal !== diffTotal) {
    notice.textContent = `Reminder: Theory + Problem-Solving total (${typeTotal}) must equal Difficulty total (${diffTotal}).`;
    notice.className = "notice warning";
  } else if (notice) {
    notice.textContent = "";
    notice.className = "notice";
  }
}

function normalizeDifficulty(value) {
  const v = String(value || "").toLowerCase();
  if (v === "moderate") return "medium";
  if (v === "difficult") return "hard";
  return v;
}

function isMultipleChoiceQuestion(q) {
  return Array.isArray(q.choices) && q.choices.filter(Boolean).length > 0;
}

function getQuestionAvailability(pool) {
  const availability = {
    theory: { easy: 0, medium: 0, hard: 0 },
    problem: { easy: 0, medium: 0, hard: 0 }
  };
  pool.forEach(q => {
    const type = q.type === "problem" ? "problem" : "theory";
    const diff = normalizeDifficulty(q.difficulty);
    if (availability[type] && availability[type][diff] !== undefined) availability[type][diff]++;
  });
  return availability;
}

function buildAvailabilityMessage(requested, availability) {
  return [
    "Not enough approved questions for the requested quiz composition.",
    "",
    `Requested Theory: Easy ${requested.theory.easy}, Moderate ${requested.theory.medium}, Difficult ${requested.theory.hard}`,
    `Available Theory: Easy ${availability.theory.easy}, Moderate ${availability.theory.medium}, Difficult ${availability.theory.hard}`,
    `Requested Problem Solving: Easy ${requested.problem.easy}, Moderate ${requested.problem.medium}, Difficult ${requested.problem.hard}`,
    `Available Problem Solving: Easy ${availability.problem.easy}, Moderate ${availability.problem.medium}, Difficult ${availability.problem.hard}`,
    "",
    "Please reduce the requested items, choose more topics, change the format, or ask the admin to approve/add more questions."
  ].join("\n");
}

function findDifficultyTypeAllocation(typeCounts, diffCounts, availability) {
  const theoryTotal = typeCounts.theory;
  const problemTotal = typeCounts.problem;
  const easyTotal = diffCounts.easy;
  const mediumTotal = diffCounts.medium;
  const hardTotal = diffCounts.hard;

  for (let te = 0; te <= Math.min(theoryTotal, easyTotal, availability.theory.easy); te++) {
    for (let tm = 0; tm <= Math.min(theoryTotal - te, mediumTotal, availability.theory.medium); tm++) {
      const th = theoryTotal - te - tm;
      const pe = easyTotal - te;
      const pm = mediumTotal - tm;
      const ph = hardTotal - th;
      if (th < 0 || pe < 0 || pm < 0 || ph < 0) continue;
      if (pe + pm + ph !== problemTotal) continue;
      const requested = {
        theory: { easy: te, medium: tm, hard: th },
        problem: { easy: pe, medium: pm, hard: ph }
      };
      if (
        requested.theory.hard <= availability.theory.hard &&
        requested.problem.easy <= availability.problem.easy &&
        requested.problem.medium <= availability.problem.medium &&
        requested.problem.hard <= availability.problem.hard
      ) {
        return requested;
      }
    }
  }
  return null;
}

function selectAdvancedQuizQuestions(pool, typeCounts, diffCounts) {
  const availability = getQuestionAvailability(pool);
  const allocation = findDifficultyTypeAllocation(typeCounts, diffCounts, availability);
  if (!allocation) {
    return { questions: [], allocation: null, availability };
  }

  const selected = [];
  ["theory", "problem"].forEach(type => {
    ["easy", "medium", "hard"].forEach(diff => {
      const needed = allocation[type][diff];
      if (!needed) return;
      const cell = shuffleArray(pool.filter(q => (q.type === "problem" ? "problem" : "theory") === type && normalizeDifficulty(q.difficulty) === diff));
      selected.push(...cell.slice(0, needed));
    });
  });

  return { questions: shuffleArray(selected), allocation, availability };
}

let lastWrongQuestions = [];
let activeQuizMode = "exam";

function renderPracticeFeedback(q) {
  if (activeQuizMode !== "practice") return "";
  const answer = userAnswers[currentIndex];
  if (!answer) return `<p class="muted-text">Practice Mode: answer first to show the explanation.</p>`;
  const correctAnswer = q.displayAnswer || q.answer;
  const isCorrect = normalizeAnswer(answer) === normalizeAnswer(q.answer) || normalizeAnswer(answer) === normalizeAnswer(correctAnswer);
  return `
    <div class="practice-feedback ${isCorrect ? "correct-box" : "wrong-box"}">
      <p><strong>${isCorrect ? "Correct" : "Needs Review"}</strong></p>
      <p><strong>Correct Answer:</strong> ${escapeHtml(String(correctAnswer || ""))}</p>
      <div><strong>Explanation:</strong><div class="review-explanation-content">${renderQuizContent(q.explanation || "No explanation saved.")}</div></div>
    </div>
  `;
}

function getPerformanceByTopic(reviewItems) {
  const stats = {};
  (reviewItems || []).forEach(item => {
    const topic = item.topic || "Unclassified";
    if (!stats[topic]) stats[topic] = { score: 0, total: 0 };
    stats[topic].total += 1;
    if (item.isCorrect) stats[topic].score += 1;
  });
  return Object.entries(stats).map(([topic, s]) => `
    <tr>
      <td>${escapeHtml(topic)}</td>
      <td>${s.score}/${s.total}</td>
      <td>${Math.round((s.score / s.total) * 100)}%</td>
    </tr>
  `).join("");
}

function retakeWrongAnswersOnly() {
  if (!lastWrongQuestions.length) {
    alert("No wrong answers to retake.");
    return;
  }
  currentQuiz = shuffleArray(lastWrongQuestions).map(q => ({ ...q, choices: Array.isArray(q.choices) ? shuffleArray(q.choices) : q.choices }));
  currentIndex = 0;
  userAnswers = Array(currentQuiz.length).fill("");
  activeQuizUsesPaidCredits = false;
  activeQuizCreditCost = 0;
  activeQuizMode = "practice";
  clearInterval(timerInterval);
  document.getElementById("timerDisplay").textContent = "Retake Mode";
  showPage("quiz-taking");
  renderQuestion();
}


function startQuickQuiz() {
  const theory = document.getElementById("theoryItemCount");
  const problem = document.getElementById("problemItemCount");
  const easy = document.getElementById("easyItemCount");
  const medium = document.getElementById("mediumItemCount");
  const hard = document.getElementById("hardItemCount");
  if (theory) theory.value = 3;
  if (problem) problem.value = 2;
  if (easy) easy.value = 2;
  if (medium) medium.value = 2;
  if (hard) hard.value = 1;
  const mode = document.getElementById("quizMode");
  if (mode) mode.value = "practice";
  const timer = document.getElementById("enableTimer");
  if (timer) timer.checked = false;
  if (typeof updateAdvancedQuizTotals === "function") updateAdvancedQuizTotals();
  generateQuiz({ preventDefault() {} });
}
async function generateQuiz(event) {
  event.preventDefault();
  const selectedTopics = getSelectedQuizTopics();
  const problemFormat = document.getElementById("problemSolvingFormat")?.value || "mixed";
  const typeCounts = {
    theory: getNumberValue("theoryItemCount"),
    problem: getNumberValue("problemItemCount")
  };
  const diffCounts = {
    easy: getNumberValue("easyItemCount"),
    medium: getNumberValue("mediumItemCount"),
    hard: getNumberValue("hardItemCount")
  };
  const typeTotal = typeCounts.theory + typeCounts.problem;
  const diffTotal = diffCounts.easy + diffCounts.medium + diffCounts.hard;

  if (typeTotal <= 0) {
    alert("Please enter at least one Theory or Problem-Solving item.");
    return;
  }
  if (typeTotal !== diffTotal) {
    alert(`Theory + Problem-Solving total (${typeTotal}) must equal Easy + Moderate + Difficult total (${diffTotal}).`);
    return;
  }

  let basePool = quizBank.filter(q => {
    const topicObj = topics.find(t => t.id === q.topic);
    const topicMatch = selectedTopics.includes("all") || selectedTopics.includes(q.topic);
    const approvedMatch = currentUser?.role === "admin" || (q.reviewStatus || "approved") === "approved";
    const diff = normalizeDifficulty(q.difficulty);
    const difficultyMatch = ["easy", "medium", "hard"].includes(diff);
    const typeMatch = q.type === "theory" || q.type === "problem";
    if (!topicMatch || !approvedMatch || !difficultyMatch || !typeMatch) return false;
    if (q.type === "problem") {
      const hasChoices = isMultipleChoiceQuestion(q);
      if (problemFormat === "multiple-choice" && !hasChoices) return false;
      if (problemFormat === "open-ended" && hasChoices) return false;
    }
    return true;
  });

  const selection = selectAdvancedQuizQuestions(basePool, typeCounts, diffCounts);
  if (!selection.questions.length) {
    const requested = {
      theory: { easy: 0, medium: 0, hard: 0 },
      problem: { easy: 0, medium: 0, hard: 0 }
    };
    alert(buildAvailabilityMessage(requested, selection.availability));
    return;
  }

  const filtered = selection.questions.map(hydrateQuestion);

  if (currentUser?.role === "student") {
    await refreshCurrentUser();
    const credits = Number(currentUser.quizCredits || 0);
    if (credits < filtered.length) {
      alert(`Payment approval is required before generating a quiz. You need ${filtered.length} quiz credit(s), but you currently have ${credits}. Please submit payment at ₱2 per question and wait for admin approval.`);
      const panel = document.getElementById("paymentPanel");
      if (panel) panel.classList.remove("hidden-panel");
      const itemInput = document.getElementById("paymentItemCount");
      if (itemInput) itemInput.value = filtered.length;
      updatePaymentTotal();
      renderMyPaymentRequests();
      return;
    }
    try {
      await consumeQuizCredits(filtered.length);
      activeQuizUsesPaidCredits = true;
      activeQuizCreditCost = filtered.length;
    } catch (error) {
      alert(error.message);
      return;
    }
  } else {
    activeQuizUsesPaidCredits = false;
    activeQuizCreditCost = 0;
  }

  currentQuiz = filtered;
  currentIndex = 0;
  userAnswers = Array(currentQuiz.length).fill("");
  activeQuizMode = document.getElementById("quizMode")?.value || "exam";

  if (document.getElementById("enableTimer").checked) {
    remainingSeconds = Number(document.getElementById("timerMinutes").value) * 60;
    startTimer();
  } else {
    clearInterval(timerInterval);
    document.getElementById("timerDisplay").textContent = activeQuizMode === "practice" ? "Practice Mode" : "No Timer";
  }

  showPage("quiz-taking");
  renderQuestion();
}

function startTimer() {
  clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    remainingSeconds--;
    updateTimerDisplay();
    if (remainingSeconds <= 0) {
      clearInterval(timerInterval);
      finishQuiz();
    }
  }, 1000);
  updateTimerDisplay();
}

function updateTimerDisplay() {
  const minutes = Math.floor(remainingSeconds / 60);
  const seconds = remainingSeconds % 60;
  document.getElementById("timerDisplay").textContent = `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function renderQuestion() {
  const q = currentQuiz[currentIndex];
  const box = document.getElementById("quizQuestionBox");
  document.getElementById("quizTitle").textContent = `Question ${currentIndex + 1} of ${currentQuiz.length}`;

  let answerArea = "";
  if (q.choices && q.choices.length > 0) {
    answerArea = q.choices.map(choice => `
      <button class="choice ${userAnswers[currentIndex] === choice ? "selected" : ""}" onclick="selectAnswer('${escapeChoice(choice)}')">${escapeHtml(choice)}</button>
    `).join("");
  } else {
    answerArea = `<input id="typedAnswer" placeholder="Enter answer. Example: 100000" value="${userAnswers[currentIndex] || ""}" oninput="userAnswers[currentIndex] = this.value" />`;
  }

  box.innerHTML = `
    <p class="eyebrow">${q.type.toUpperCase()} • ${q.difficulty.toUpperCase()}</p>
    <div class="quiz-question-text">${renderQuizContent(q.question)}</div>
    ${answerArea}
    ${renderPracticeFeedback(q)}
    <div class="quiz-controls">
      <button class="btn ghost" onclick="previousQuestion()" ${currentIndex === 0 ? "disabled" : ""}>Previous</button>
      ${currentIndex === currentQuiz.length - 1
        ? `<button class="btn primary" onclick="finishQuiz()">Submit Quiz</button>`
        : `<button class="btn primary" onclick="nextQuestion()">Next</button>`}
    </div>
  `;
}

function escapeChoice(choice) {
  return choice.replace(/'/g, "\\'");
}

function selectAnswer(answer) {
  userAnswers[currentIndex] = answer;
  renderQuestion();
}

function nextQuestion() {
  if (currentIndex < currentQuiz.length - 1) {
    currentIndex++;
    renderQuestion();
  }
}

function previousQuestion() {
  if (currentIndex > 0) {
    currentIndex--;
    renderQuestion();
  }
}

function normalizeAnswer(value) {
  return String(value).replace(/[₱,\s]/g, "").toLowerCase();
}

function renderReviewItems(items) {
  return (items || []).map((item, index) => `
    <div class="result-item">
      <div><strong>Question ${index + 1}:</strong> <div class="review-question-content">${renderQuizContent(item.question)}</div></div>
      <p>Your Answer: <span class="${item.isCorrect ? "correct" : "wrong"}">${escapeHtml(String(item.userAnswer || "No answer"))}</span></p>
      <p>Correct Answer: <strong>${escapeHtml(String(item.correctAnswer || ""))}</strong></p>
      <div><strong>Explanation:</strong> <div class="review-explanation-content">${renderQuizContent(item.explanation || "No explanation saved.")}</div></div>
    </div>
  `).join("");
}

function getLocalQuizHistory() {
  const all = JSON.parse(localStorage.getItem("farQuizHistory") || "[]");
  if (!currentUser) return [];
  return all.filter(h => h.studentEmail === currentUser.email);
}

function saveLocalQuizHistory(record) {
  if (!currentUser || currentUser.role !== "student") return;
  const all = JSON.parse(localStorage.getItem("farQuizHistory") || "[]");
  all.unshift(record);
  localStorage.setItem("farQuizHistory", JSON.stringify(all.slice(0, 100)));
}

async function getQuizHistory() {
  let history = getLocalQuizHistory();
  if (API_BASE_URL && currentUser?.role === "student") {
    try {
      const response = await fetch(`${API_BASE_URL}/api/my-scores`, { headers: getAuthHeaders() });
      const data = await response.json();
      if (response.ok) history = data;
    } catch (error) {
      console.warn("Unable to load backend quiz history.", error);
    }
  }
  return history.sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
}

async function renderQuizHistory() {
  const box = document.getElementById("quizHistoryBox");
  if (!box) return;
  if (!currentUser || currentUser.role !== "student") {
    box.innerHTML = "<p>Please log in as a student to view quiz history.</p>";
    return;
  }
  box.innerHTML = "<p>Loading quiz history...</p>";
  const history = await getQuizHistory();
  if (!history.length) {
    box.innerHTML = "<p>No quiz history yet. Take a quiz first, then your results will appear here for review.</p>";
    return;
  }
  box.innerHTML = history.map((record, idx) => `
    <details class="history-record" ${idx === 0 ? "open" : ""}>
      <summary>
        <strong>${new Date(record.createdAt).toLocaleString()}</strong> — Score: ${record.score}/${record.total} (${record.percentage}%)
      </summary>
      <div class="history-review">
        ${renderReviewItems(record.reviewItems || [])}
      </div>
    </details>
  `).join("");
}

async function finishQuiz() {
  clearInterval(timerInterval);
  let score = 0;

  const reviewItems = currentQuiz.map((q, index) => {
    const userAnswer = userAnswers[index] || "No answer";
    const correctAnswer = q.displayAnswer || q.answer;
    const isCorrect = normalizeAnswer(userAnswer) === normalizeAnswer(q.answer) || normalizeAnswer(userAnswer) === normalizeAnswer(correctAnswer);
    if (isCorrect) score++;
    return {
      question: q.question,
      userAnswer,
      correctAnswer,
      explanation: q.explanation,
      isCorrect,
      topic: q.topic,
      type: q.type,
      difficulty: q.difficulty
    };
  });

  const review = renderReviewItems(reviewItems);
  lastWrongQuestions = currentQuiz.filter((q, index) => !reviewItems[index].isCorrect);
  const performanceRows = getPerformanceByTopic(reviewItems);

  const percentage = Math.round((score / currentQuiz.length) * 100);

  if (API_BASE_URL) {
    try {
      await fetch(`${API_BASE_URL}/api/scores`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ score, total: currentQuiz.length, percentage, reviewItems })
      });
    } catch (error) {
      console.warn("Score was not saved to backend.", error);
    }
  }
  saveLocalQuizHistory({
    id: Date.now().toString(),
    studentEmail: currentUser?.email || "local-student",
    studentName: currentUser?.name || "Student",
    score,
    total: currentQuiz.length,
    percentage,
    reviewItems,
    createdAt: new Date().toISOString()
  });

  document.getElementById("resultBox").innerHTML = `
    <h2>Quiz Results</h2>
    <h3>Score: ${score} / ${currentQuiz.length}</h3>
    <p><strong>Percentage:</strong> ${percentage}%</p>
    ${activeQuizUsesPaidCredits ? `<p class="notice success">${activeQuizCreditCost} paid quiz credit(s) used for this quiz.</p>` : ""}
    <p><span class="correct">Correct:</span> ${score} | <span class="wrong">Wrong:</span> ${currentQuiz.length - score}</p>
    <h3>Performance by Topic</h3>
    <table class="performance-table"><thead><tr><th>Topic</th><th>Score</th><th>Percentage</th></tr></thead><tbody>${performanceRows}</tbody></table>
    ${lastWrongQuestions.length ? `<button class="btn secondary" onclick="retakeWrongAnswersOnly()">Retake Wrong Answers Only</button>` : ""}
    <hr />
    <h3>Review Answers</h3>
    ${review}
    <button class="btn primary" onclick="showPage('quizzer')">Create Another Quiz</button>
    <button class="btn secondary" onclick="showPage('quiz-history')">View Quiz History</button>
    <button class="btn ghost" onclick="showPage('topics')">Back to Topics</button>
  `;

  showPage("quiz-result");
}


function getStudentStorageKey(suffix) {
  return `far_${suffix}_${currentUser?.email || "guest"}`;
}

function markLessonViewed(topicId, lessonId) {
  if (!currentUser || currentUser.role !== "student") return;
  const key = getStudentStorageKey("viewedLessons");
  const viewed = JSON.parse(localStorage.getItem(key) || "{}");
  viewed[topicId] ||= [];
  if (!viewed[topicId].includes(lessonId)) viewed[topicId].push(lessonId);
  localStorage.setItem(key, JSON.stringify(viewed));
  localStorage.setItem(getStudentStorageKey("lastLesson"), JSON.stringify({ topicId, lessonId, viewedAt: new Date().toISOString() }));
}

function getTopicLessonCount(topic) {
  return 2 + ((topic?.tabs || []).length); // Discussion + custom tabs + Practice
}

function getTopicTitle(topicId) {
  return topics.find(t => t.id === topicId)?.title || topicId || "Topic";
}


function hideStudentHomePanelForPage(pageId) {
  const panel = document.getElementById("studentHomePanel");
  if (!panel) return;
  const shouldShow = currentUser?.role === "student" && (pageId === "student" || pageId === "home");
  panel.style.display = shouldShow ? "" : "none";
}

function scrollToActivePage(pageId) {
  const target = document.getElementById(pageId);
  if (!target) return;
  setTimeout(() => target.scrollIntoView({ behavior: "smooth", block: "start" }), 80);
}

function goToStudentSection(pageId, openPayment = false) {
  showPage(pageId);
  scrollToActivePage(pageId);
  if (pageId === "quizzer" && openPayment) {
    setTimeout(() => {
      const panel = document.getElementById("paymentRequestPanel");
      if (panel && panel.classList.contains("hidden-panel")) togglePaymentPanel && togglePaymentPanel();
      const quizzer = document.getElementById("quizzer");
      if (quizzer) quizzer.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 250);
  }
}


function goToAdminStudentView() {
  if (!currentUser) return showPage("login");
  if (currentUser.role !== "admin") return showPage("student");
  showPage("admin");
  setTimeout(() => {
    showAdminSection("admin-student-view");
    const preview = document.getElementById("admin-student-view");
    if (preview) preview.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 120);
}

function continueLastLesson() {
  if (!currentUser || currentUser.role !== "student") return showPage("login");
  const last = JSON.parse(localStorage.getItem(getStudentStorageKey("lastLesson")) || "null");
  if (!last || !topics.some(t => t.id === last.topicId)) return goToStudentSection("topics");
  openTopic(last.topicId);
  setTimeout(() => {
    showTopicLesson(last.topicId, last.lessonId || "discussion");
    scrollToActivePage("topic-detail");
  }, 120);
}

function summarizeStudentPerformance(history) {
  const grouped = {};
  history.forEach(record => (record.reviewItems || []).forEach(item => {
    const topicId = item.topic || "General";
    grouped[topicId] ||= { correct: 0, total: 0 };
    grouped[topicId].total += 1;
    if (item.isCorrect) grouped[topicId].correct += 1;
  }));
  const rows = Object.entries(grouped).map(([topicId, data]) => ({
    topicId,
    title: getTopicTitle(topicId),
    correct: data.correct,
    total: data.total,
    percent: data.total ? Math.round((data.correct / data.total) * 100) : 0
  })).sort((a, b) => b.percent - a.percent);
  return rows;
}

async function renderStudentHome() {
  if (!currentUser || currentUser.role !== "student") return;

  const greeting = document.getElementById("studentHomeGreeting");
  if (greeting) greeting.textContent = `Hi, ${currentUser.name || currentUser.email}!`;

  const status = getTrialStatus(currentUser);
  const trialStatus = document.getElementById("homeTrialStatus");
  const daysLeft = document.getElementById("homeDaysLeft");
  const credits = document.getElementById("homeQuizCredits");
  if (trialStatus) trialStatus.textContent = status.active ? "Active" : "Expired";
  if (daysLeft) daysLeft.textContent = status.daysRemaining ?? "—";
  if (credits) credits.textContent = Number(currentUser.quizCredits || 0);

  const announcementBox = document.getElementById("homeAnnouncementBox");
  if (announcementBox) announcementBox.innerHTML = renderAccountingContent(siteSettings.announcement || "No announcement yet.");

  const last = JSON.parse(localStorage.getItem(getStudentStorageKey("lastLesson")) || "null");
  const continueBox = document.getElementById("continueLearningBox");
  if (continueBox) {
    if (last && topics.some(t => t.id === last.topicId)) {
      const lessonTitle = last.lessonId === "practice" ? "Practice" : last.lessonId === "discussion" ? "Discussion" : ((topics.find(t => t.id === last.topicId)?.tabs || []).find(tab => tab.id === last.lessonId)?.title || "Lesson");
      continueBox.innerHTML = `<strong>${escapeHtml(getTopicTitle(last.topicId))}</strong><br>${escapeHtml(lessonTitle)}<br><small>Last opened: ${new Date(last.viewedAt || Date.now()).toLocaleString()}</small><br><button class="btn secondary small-btn" onclick="continueLastLesson()">Continue Lesson</button>`;
    } else {
      continueBox.innerHTML = `No lesson viewed yet.<br><button class="btn secondary small-btn" onclick="goToStudentSection('topics')">Choose a Topic</button>`;
    }
  }

  const viewed = JSON.parse(localStorage.getItem(getStudentStorageKey("viewedLessons")) || "{}");
  const progressGrid = document.getElementById("homeTopicProgressGrid");
  if (progressGrid) {
    const startedTopics = topics
      .map(topic => {
        const viewedCount = new Set(viewed[topic.id] || []).size;
        const totalLessons = Math.max(1, getTopicLessonCount(topic));
        const pct = Math.min(100, Math.round((viewedCount / totalLessons) * 100));
        return { ...topic, viewedCount, totalLessons, pct, subject: topic.subject || "FAR" };
      })
      .filter(topic => topic.viewedCount > 0);

    if (!startedTopics.length) {
      progressGrid.innerHTML = `<div class="empty-state progress-empty-state">No topic progress yet. Start a lesson to see your progress here.</div>`;
    } else {
      const groupedBySubject = SUBJECTS
        .map(subject => ({ ...subject, topics: startedTopics.filter(topic => topic.subject === subject.id) }))
        .filter(group => group.topics.length);

      progressGrid.innerHTML = groupedBySubject.map(group => `
        <section class="topic-progress-subject-group" style="--subject-primary:${getSubjectColor(group.id)}">
          <div class="topic-progress-subject-header">
            <span class="subject-badge" style="background:${getSubjectColor(group.id)}">${escapeHtml(group.id)}</span>
            <h4>${escapeHtml(group.name)} Progress</h4>
          </div>
          <div class="topic-progress-card-grid">
            ${group.topics.map(topic => `
              <div class="topic-progress-card">
                <h4>${escapeHtml(topic.title)}</h4>
                <div class="progress-bar"><span style="width:${topic.pct}%"></span></div>
                <p>${topic.viewedCount}/${topic.totalLessons} lesson tab(s) viewed</p>
                <button class="btn ghost small-btn" onclick="openTopic('${escapeJs(topic.id)}')">Continue Topic</button>
              </div>
            `).join("")}
          </div>
        </section>
      `).join("");
    }
  }

  const history = await getQuizHistory();
  const recentBox = document.getElementById("homeRecentQuizResults");
  if (recentBox) {
    recentBox.innerHTML = history.length ? `<ul>${history.slice(0, 3).map(record => `<li><strong>${record.score}/${record.total}</strong> (${record.percentage}%) — ${new Date(record.createdAt).toLocaleDateString()} <button class="btn ghost small-btn home-review-link" onclick="goToStudentSection('quiz-history')">View</button></li>`).join("")}</ul>` : `No recent quiz results yet.<br><button class="btn secondary small-btn" onclick="goToStudentSection('quizzer')">Take First Quiz</button>`;
  }

  const performance = summarizeStudentPerformance(history);
  const perfBox = document.getElementById("homePerformanceSummary");
  const recBox = document.getElementById("homeRecommendedReview");
  if (perfBox) {
    if (performance.length) {
      const totalCorrect = performance.reduce((s, r) => s + r.correct, 0);
      const totalItems = performance.reduce((s, r) => s + r.total, 0);
      const average = totalItems ? Math.round((totalCorrect / totalItems) * 100) : 0;
      perfBox.innerHTML = `<p><strong>Overall Average:</strong> ${average}%</p><p><strong>Strongest Topic:</strong> ${escapeHtml(performance[0].title)} (${performance[0].percent}%)</p><p><strong>Needs Improvement:</strong> ${escapeHtml(performance[performance.length - 1].title)} (${performance[performance.length - 1].percent}%)</p>`;
    } else {
      perfBox.innerHTML = `No quiz performance yet.<br><button class="btn secondary small-btn" onclick="goToStudentSection('quizzer')">Start Quiz Practice</button>`;
    }
  }
  if (recBox) {
    if (performance.length) {
      const weak = performance[performance.length - 1];
      recBox.innerHTML = `Focus on <strong>${escapeHtml(weak.title)}</strong>. Your current result is ${weak.correct}/${weak.total} (${weak.percent}%).<br><button class="btn secondary small-btn" onclick="goToStudentSection('quizzer')">Review This Topic</button>`;
    } else {
      recBox.innerHTML = `Take a diagnostic quiz first. The system will recommend your weakest topic after your first result.`;
    }
  }
}

function loadSiteSettingsEditor() {
  const input = document.getElementById("adminAnnouncementInput");
  if (input) input.value = siteSettings.announcement || "";
}

async function saveSiteSettings() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const input = document.getElementById("adminAnnouncementInput");
  siteSettings.announcement = (input?.value || "").trim();
  if (API_BASE_URL) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/admin/site-settings`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify(siteSettings)
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Unable to save site settings.");
      siteSettings = { ...siteSettings, ...data };
    } catch (error) {
      setMessage("siteSettingsMessage", error.message, "error");
      return;
    }
  } else {
    localStorage.setItem("farSiteSettings", JSON.stringify(siteSettings));
  }
  setMessage("siteSettingsMessage", "Announcement saved.", "success");
  renderStudentHome();
}

let adminStudentCache = [];

async function loadStudentsForAdmin() {
  const box = document.getElementById("studentsList");
  if (!box || currentUser?.role !== "admin") return;
  let users = [];

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users`, { headers: getAuthHeaders() });
    users = await response.json();
  } else {
    users = [...getLocalDemoUsers(), ...JSON.parse(localStorage.getItem("farUsers") || "[]")].map(u => ({
      id: u.id || u.email,
      name: u.name || u.fullName || "",
      contactNumber: u.contactNumber || "",
      email: u.email,
      role: u.role,
      approvalStatus: u.approvalStatus || "approved",
      trialStartDate: u.trialStartDate,
      trialEndDate: u.trialEndDate,
      trialDays: u.trialDays,
      quizCredits: Number(u.quizCredits || 0),
      subjectSubscriptions: u.subjectSubscriptions || {}
    }));
  }

  adminStudentCache = users.filter(u => u.role === "student");
  renderStudentManagementTable();
}

function renderStudentManagementTable() {
  const box = document.getElementById("studentsList");
  if (!box) return;
  const query = (document.getElementById("studentManagementSearch")?.value || "").toLowerCase().trim();
  const statusFilter = document.getElementById("studentManagementStatusFilter")?.value || "all";
  let students = [...adminStudentCache];

  students = students.filter(student => {
    const trial = getTrialStatus(student);
    const approval = student.approvalStatus || "approved";
    const haystack = `${student.name || ""} ${student.email || ""} ${student.contactNumber || ""} ${approval}`.toLowerCase();
    const matchesSearch = !query || haystack.includes(query);
    let matchesStatus = true;
    if (statusFilter === "expired") matchesStatus = approval === "approved" && !trial.active;
    else if (statusFilter === "zero_credit") matchesStatus = Number(student.quizCredits || 0) <= 0;
    else if (statusFilter !== "all") matchesStatus = approval === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const pendingCount = adminStudentCache.filter(s => s.approvalStatus === "pending_approval").length;
  const zeroCredits = adminStudentCache.filter(s => Number(s.quizCredits || 0) <= 0).length;
  const summary = document.getElementById("studentApprovalSummary");
  if (summary) summary.textContent = `${pendingCount} pending approval • ${zeroCredits} student(s) with zero quiz credits • ${students.length} record(s) shown`;

  if (!students.length) {
    box.innerHTML = `<p class="muted-text">No student records match the selected filter.</p>`;
    return;
  }

  box.innerHTML = `
    <div class="responsive-table-wrap">
      <table class="admin-health-table student-management-table">
        <thead>
          <tr><th>Name</th><th>Email</th><th>Status</th><th>Trial</th><th>Credits</th><th>Action</th></tr>
        </thead>
        <tbody>
          ${students.map(student => {
            const trial = getTrialStatus(student);
            const approval = student.approvalStatus || "approved";
            const safeId = escapeHtml(student.id || student.email);
            const safeEmail = escapeHtml(student.email || "");
            const safeName = escapeHtml(student.name || "No name saved");
            return `<tr>
              <td><strong>${safeName}</strong><br><small>${escapeHtml(student.contactNumber || "No contact")}</small></td>
              <td>${safeEmail}</td>
              <td><span class="status-pill ${approval}">${escapeHtml(approval.replace("_", " "))}</span></td>
              <td>${escapeHtml(trial.message)}<br><small>${student.trialEndDate ? new Date(student.trialEndDate).toLocaleDateString() : "No date"}</small></td>
              <td><strong>${Number(student.quizCredits || 0)}</strong></td>
              <td><button class="btn small-btn secondary" onclick="toggleStudentManagePanel('${safeId}')">Manage</button></td>
            </tr>
            <tr id="manage-${safeId}" class="student-manage-row" style="display:none"><td colspan="6">${buildStudentManagePanel(student)}</td></tr>`;
          }).join("")}
        </tbody>
      </table>
    </div>`;
}

function buildStudentManagePanel(student) {
  const approval = student.approvalStatus || "approved";
  const status = getTrialStatus(student);
  const safeId = escapeHtml(student.id || student.email);
  const safeEmail = escapeHtml(student.email || "");
  let removeButton = "";
  if (approval === "rejected") removeButton = `<button class="btn danger-btn" onclick="removeStudentAccount('${safeId}', '${safeEmail}', 'rejected')">Remove Rejected Email</button>`;
  else if (approval === "approved" && !status.active) removeButton = `<button class="btn danger-btn" onclick="removeStudentAccount('${safeId}', '${safeEmail}', 'expired')">Remove Expired Email</button>`;
  else if (approval === "approved") removeButton = `<button class="btn danger-btn" onclick="removeStudentAccount('${safeId}', '${safeEmail}', 'approved')">Remove Approved Email</button>`;

  return `<div class="student-manage-panel">
    <div class="button-row">
      <button class="btn secondary" onclick="updateStudentApproval('${safeId}', 'approved')">Approve</button>
      <button class="btn ghost" onclick="updateStudentApproval('${safeId}', 'rejected')">Reject</button>
      ${removeButton}
    </div>
    <div class="admin-filter-bar compact-management-controls">
      <div><label>Trial Days</label><input type="number" min="1" value="7" id="days-${safeId}" /></div>
      <div class="button-stack"><button class="btn secondary" onclick="addTrialDays('${safeId}')">Add Days</button><button class="btn danger-btn" onclick="reduceTrialDays('${safeId}')">Reduce Days</button></div>
      <div><label>Quiz Credits</label><input type="number" min="1" value="10" id="credits-${safeId}" /></div>
      <div class="button-stack"><button class="btn secondary" onclick="addQuizCredits('${safeId}')">Add Credits</button><button class="btn danger-btn" onclick="reduceQuizCredits('${safeId}')">Reduce Credits</button></div>
    </div>
  </div>`;
}

function toggleStudentManagePanel(userId) {
  const row = document.getElementById(`manage-${userId}`);
  if (!row) return;
  const visible = row.style.display !== "none";
  document.querySelectorAll(".student-manage-row").forEach(r => r.style.display = "none");
  row.style.display = visible ? "none" : "table-row";
}

async function updateStudentApproval(userId, approvalStatus) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${userId}/approval`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ approvalStatus })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to update approval status.");
  } else {
    for (const key of ["farDemoUsers", "farUsers"]) {
      const users = JSON.parse(localStorage.getItem(key) || "[]");
      const user = users.find(u => (u.id || u.email) === userId);
      if (user && user.role === "student") {
        user.approvalStatus = approvalStatus;
        user.approvedAt = approvalStatus === "approved" ? new Date().toISOString() : user.approvedAt;
        user.approvedBy = approvalStatus === "approved" ? currentUser.email : user.approvedBy;
        localStorage.setItem(key, JSON.stringify(users));
      }
    }
  }

  await loadStudentsForAdmin();
  alert(`Student account marked as ${approvalStatus.replace("_", " ")}.`);
}

async function removeStudentAccount(userId, email, reason = "student") {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const label = reason === "expired" ? "expired email" : reason === "approved" ? "approved email" : "rejected email";
  const confirmed = confirm(`Remove ${label} ${email}? This will permanently delete the student registration record.`);
  if (!confirmed) return;

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${userId}`, {
      method: "DELETE",
      headers: getAuthHeaders()
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || `Unable to remove ${label}.`);
  } else {
    let removed = false;
    for (const key of ["farDemoUsers", "farUsers"]) {
      const users = JSON.parse(localStorage.getItem(key) || "[]");
      const user = users.find(u => (u.id || u.email) === userId);
      const trialStatus = getTrialStatus(user);
      const approval = user?.approvalStatus || "approved";
      const canRemove = user && user.role === "student" && (approval === "rejected" || approval === "approved" || !trialStatus.active);
      if (canRemove) {
        const updatedUsers = users.filter(u => (u.id || u.email) !== userId);
        localStorage.setItem(key, JSON.stringify(updatedUsers));
        removed = true;
      }
    }
    if (!removed) return alert("Only rejected, approved, or expired student accounts can be removed.");
  }

  await loadStudentsForAdmin();
  alert("Student email removed successfully.");
}

async function addTrialDays(userId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const days = Number(document.getElementById(`days-${userId}`).value);
  if (!days || days <= 0) return alert("Enter valid number of days.");

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/add-trial-days`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ days })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add days.");
  } else {
    for (const key of ["farDemoUsers", "farUsers"]) {
      const users = JSON.parse(localStorage.getItem(key) || "[]");
      const user = users.find(u => (u.id || u.email) === userId);
      if (user && user.role === "student") {
        const base = user.trialEndDate && new Date(user.trialEndDate) > new Date() ? new Date(user.trialEndDate) : new Date();
        user.trialEndDate = addDays(base, days).toISOString();
        user.trialDays = Number(user.trialDays || 30) + days;
        localStorage.setItem(key, JSON.stringify(users));
        if (currentUser.email === user.email) {
          currentUser = { ...currentUser, trialEndDate: user.trialEndDate, trialDays: user.trialDays };
          localStorage.setItem("farCurrentUser", JSON.stringify(currentUser));
        }
      }
    }
  }
  await loadStudentsForAdmin();
  alert(`${days} trial day(s) added.`);
}

async function reduceTrialDays(userId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const input = document.getElementById(`days-${userId}`);
  if (!input) return alert("Trial days input not found.");
  const days = Number(input.value);
  if (!days || days <= 0) return alert("Enter valid number of days to reduce.");
  if (!confirm(`Reduce this student's trial access by ${days} day(s)?`)) return;

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/reduce-trial-days`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ days })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to reduce days.");
    alert(data.message || `${days} trial day(s) reduced.`);
  } else {
    let updated = null;
    for (const key of ["farDemoUsers", "farUsers"]) {
      const users = JSON.parse(localStorage.getItem(key) || "[]");
      const user = users.find(u => (u.id || u.email) === userId);
      if (user && user.role === "student") {
        const currentEnd = user.trialEndDate ? new Date(user.trialEndDate) : new Date();
        user.trialEndDate = addDays(currentEnd, -days).toISOString();
        user.trialDays = Math.max(0, Number(user.trialDays || 30) - days);
        user.updatedAt = new Date().toISOString();
        localStorage.setItem(key, JSON.stringify(users));
        updated = user;
      }
    }
    if (!updated) return alert("Student not found.");
    alert(`${days} trial day(s) reduced from ${updated.name || updated.email}.`);
  }
  await loadStudentsForAdmin();
}

async function reduceQuizCredits(userId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const input = document.getElementById(`credits-${userId}`);
  if (!input) return alert("Quiz credits input not found.");
  const credits = Number(input.value);
  if (!credits || credits <= 0) return alert("Enter valid number of quiz credits to reduce.");
  if (!confirm(`Reduce this student's quiz credits by ${credits}?`)) return;

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/reduce-quiz-credits`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ credits })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to reduce quiz credits.");
    alert(data.message || `${credits} quiz credit(s) reduced.`);
  } else {
    const updated = updateLocalUserCredits(userId, -credits);
    if (!updated) return alert("Student not found.");
    alert(`${credits} quiz credit(s) reduced from ${updated.name || updated.email}. Current credits: ${Number(updated.quizCredits || 0)}.`);
  }
  await loadStudentsForAdmin();
}



