let adminPdfGeneratedQuiz = [];

function populateAdminPdfTopicChoices() {
  const box = document.getElementById("adminPdfTopicChoices");
  if (!box) return;
  box.innerHTML = `
    <label><input type="checkbox" name="adminPdfTopic" value="all" checked /> All Topics</label>
    ${topics.map(t => `<label><input type="checkbox" name="adminPdfTopic" value="${escapeHtml(t.id)}" /> ${escapeHtml(t.title)}</label>`).join("")}
  `;
  setupAdminPdfTopicCheckboxes();
}

function setupAdminPdfTopicCheckboxes() {
  const boxes = Array.from(document.querySelectorAll('input[name="adminPdfTopic"]'));
  if (!boxes.length) return;
  boxes.forEach(box => {
    box.onchange = () => {
      const allBox = boxes.find(item => item.value === "all");
      if (box.value === "all" && box.checked) {
        boxes.filter(item => item.value !== "all").forEach(item => item.checked = false);
      } else if (box.value !== "all" && box.checked && allBox) {
        allBox.checked = false;
      }
      if (!boxes.some(item => item.checked) && allBox) allBox.checked = true;
    };
  });
}

function setupAdminPdfDifficultyCheckboxes() {
  const boxes = Array.from(document.querySelectorAll('input[name="adminPdfDifficulty"]'));
  if (!boxes.length) return;
  boxes.forEach(box => {
    box.onchange = () => {
      const allBox = boxes.find(item => item.value === "all");
      if (box.value === "all" && box.checked) {
        boxes.filter(item => item.value !== "all").forEach(item => item.checked = false);
      } else if (box.value !== "all" && box.checked && allBox) {
        allBox.checked = false;
      }
      if (!boxes.some(item => item.checked) && allBox) allBox.checked = true;
    };
  });
}

function getAdminPdfSelectedTopics() {
  const checked = Array.from(document.querySelectorAll('input[name="adminPdfTopic"]:checked')).map(input => input.value);
  return checked.length ? checked : ["all"];
}

function getAdminPdfSelectedDifficulties() {
  const checked = Array.from(document.querySelectorAll('input[name="adminPdfDifficulty"]:checked')).map(input => input.value);
  return checked.length ? checked : ["all"];
}

function getQuestionTopicTitle(topicId) {
  const topic = topics.find(t => t.id === topicId);
  return topic ? topic.title : topicId;
}

function getAdminPdfFilteredQuestions() {
  const selectedTopics = getAdminPdfSelectedTopics();
  const type = document.getElementById("adminPdfQuizType")?.value || "mixed";
  const difficulties = getAdminPdfSelectedDifficulties();
  const count = Math.max(1, Number(document.getElementById("adminPdfItemCount")?.value || 1));

  const filtered = quizBank.filter(q => {
    const topicMatch = selectedTopics.includes("all") || selectedTopics.includes(q.topic);
    const typeMatch = type === "mixed" || q.type === type;
    const difficultyMatch = difficulties.includes("all") || difficulties.includes(q.difficulty);
    const approvedMatch = (q.reviewStatus || "approved") === "approved";
    return topicMatch && typeMatch && difficultyMatch && approvedMatch;
  });

  return shuffleArray(filtered).slice(0, count).map(hydrateQuestion);
}

function renderAdminPdfQuizHtml(questions, includeAnswerKey = true) {
  const title = document.getElementById("adminPdfQuizTitle")?.value.trim() || "Practice Quiz";
  const dateText = new Date().toLocaleDateString("en-PH", { year: "numeric", month: "long", day: "numeric" });

  const questionHtml = questions.map((q, index) => {
    const choices = Array.isArray(q.choices) && q.choices.length
      ? `<ol type="A" class="pdf-choices">${q.choices.map(choice => `<li>${escapeHtml(choice)}</li>`).join("")}</ol>`
      : `<div class="pdf-answer-line">Answer: ________________________________</div>`;
    return `
      <div class="pdf-question-item">
        <div class="pdf-question-text"><span class="question-number">${index + 1}.</span><div class="question-body">${renderQuizContent(q.question)}</div></div>
        ${choices}
      </div>
    `;
  }).join("");

  const answerKeyHtml = includeAnswerKey ? `
    <div class="pdf-answer-key page-break-before">
      <h3>Answer Key and Explanations</h3>
      ${questions.map((q, index) => `
        <div class="pdf-answer-item">
          <p><strong>${index + 1}.</strong> ${escapeHtml(q.displayAnswer || q.answer || "")}</p>
          <div class="pdf-explanation-text"><small><strong>Explanation:</strong></small> ${renderQuizContent(q.explanation || "No explanation provided.")}</div>
        </div>
      `).join("")}
    </div>` : "";

  return `
    <div class="pdf-sheet">
      <div class="pdf-header">
        <h2>${escapeHtml(title)}</h2>
        <p><strong>Date:</strong> ${escapeHtml(dateText)}</p>
        <p><strong>Name:</strong> _______________________________ &nbsp;&nbsp; <strong>Score:</strong> __________</p>
      </div>
      <div class="pdf-instructions">
        <p><strong>Instructions:</strong> Answer each question carefully. For problem-solving items, show your computation when required.</p>
      </div>
      ${questionHtml}
      ${answerKeyHtml}
    </div>
  `;
}

function generateAdminQuizPdfPreview() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const preview = document.getElementById("adminPdfPreview");
  const message = document.getElementById("adminPdfMessage");
  const includeAnswerKey = document.getElementById("adminPdfIncludeAnswerKey")?.checked ?? true;
  const questions = getAdminPdfFilteredQuestions();
  adminPdfGeneratedQuiz = questions;

  if (!questions.length) {
    if (preview) preview.innerHTML = `<p class="form-message error">No approved questions found for the selected filters.</p>`;
    if (message) message.textContent = "No approved questions found for the selected filters.";
    return;
  }

  if (preview) preview.innerHTML = renderAdminPdfQuizHtml(questions, includeAnswerKey);
  if (message) {
    message.textContent = `${questions.length} question(s) generated and ready for PDF.`;
    message.className = "form-message success";
  }
}

function printAdminQuizPdf() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (!adminPdfGeneratedQuiz.length) generateAdminQuizPdfPreview();
  if (!adminPdfGeneratedQuiz.length) return;

  const includeAnswerKey = document.getElementById("adminPdfIncludeAnswerKey")?.checked ?? true;
  const html = renderAdminPdfQuizHtml(adminPdfGeneratedQuiz, includeAnswerKey);
  const title = document.getElementById("adminPdfQuizTitle")?.value.trim() || "Practice Quiz";
  const printWindow = window.open("", "_blank");
  if (!printWindow) return alert("Please allow pop-ups so the PDF window can open.");

  printWindow.document.write(`
    <!DOCTYPE html>
    <html>
      <head>
        <title>${escapeHtml(title)}</title>
        <style>
          body { font-family: "Arial Narrow", Arial, sans-serif; font-size: 10pt; color: #111827; margin: 0; background: #ffffff; text-align: justify; }
          .pdf-sheet, .pdf-sheet * { font-family: "Arial Narrow", Arial, sans-serif !important; font-size: 10pt !important; line-height: 1.2; }
          .pdf-sheet { width: auto; min-height: auto; padding: 0; margin: 0; box-sizing: border-box; background: #fff; text-align: justify; }
          .pdf-header { text-align: center; border-bottom: 1px solid #111827; margin-bottom: 12px; padding-bottom: 8px; }
          .pdf-header h2 { margin: 0 0 6px; font-size: 10pt !important; }
          .pdf-header p { margin: 3px 0; }
          .pdf-instructions { background: #ffffff; border: 1px solid #d1d5db; padding: 8px; margin-bottom: 12px; text-align: justify; }
          .pdf-question-item { break-inside: avoid; page-break-inside: avoid; margin-bottom: 12px; text-align: justify; }
          .pdf-question-item p { margin-bottom: 6px; text-align: justify; }
          .pdf-choices { margin-top: 5px; text-align: justify; }
          .pdf-choices li { margin-bottom: 4px; text-align: justify; }
          .pdf-answer-line { margin-top: 12px; text-align: justify; }
          .pdf-answer-key { margin-top: 18px; border-top: 1px solid #111827; padding-top: 10px; text-align: justify; }
          .pdf-answer-item { break-inside: avoid; page-break-inside: avoid; margin-bottom: 10px; text-align: justify; }
          .page-break-before { page-break-before: always; break-before: page; }
          @page { size: 8.5in 13in; margin: 0.5in; }
        </style>
      </head>
      <body>${html}</body>
    </html>
  `);
  printWindow.document.close();
  printWindow.focus();
  setTimeout(() => printWindow.print(), 350);
}


function setupAdminPdfQuizOptions() {
  const topicBox = document.getElementById("adminPdfTopicChecks");
  if (topicBox) {
    topicBox.innerHTML = `
      <label><input type="checkbox" name="adminPdfTopic" value="all" checked> All Topics</label>
      ${topics.map(t => `<label><input type="checkbox" name="adminPdfTopic" value="${escapeHtml(t.id)}"> ${escapeHtml(t.title)}</label>`).join("")}
    `;
    const topicChecks = Array.from(topicBox.querySelectorAll('input[name="adminPdfTopic"]'));
    const allTopic = topicChecks.find(box => box.value === "all");
    topicChecks.forEach(box => {
      box.addEventListener("change", () => {
        if (box.value === "all" && box.checked) topicChecks.filter(item => item.value !== "all").forEach(item => { item.checked = false; });
        if (box.value !== "all" && box.checked && allTopic) allTopic.checked = false;
        if (!topicChecks.some(item => item.checked) && allTopic) allTopic.checked = true;
      });
    });
  }

  const diffBox = document.getElementById("adminPdfDifficultyChecks");
  if (diffBox && !diffBox.dataset.bound) {
    const diffChecks = Array.from(diffBox.querySelectorAll('input[name="adminPdfDifficulty"]'));
    const allDiff = diffChecks.find(box => box.value === "all");
    diffChecks.forEach(box => {
      box.addEventListener("change", () => {
        if (box.value === "all" && box.checked) diffChecks.filter(item => item.value !== "all").forEach(item => { item.checked = false; });
        if (box.value !== "all" && box.checked && allDiff) allDiff.checked = false;
        if (!diffChecks.some(item => item.checked) && allDiff) allDiff.checked = true;
      });
    });
    diffBox.dataset.bound = "true";
  }
}

function getAdminPdfSelectedValues(name) {
  const values = Array.from(document.querySelectorAll(`input[name="${name}"]:checked`)).map(input => input.value);
  return values.length ? values : ["all"];
}

function buildPrintableQuizHtml(questions, settings) {
  const showQuestions = settings.includeMode !== "answer-key-only";
  const showAnswers = settings.includeMode !== "questions-only";
  const questionHtml = questions.map((q, index) => {
    const choices = Array.isArray(q.choices) ? q.choices.filter(Boolean) : [];
    const choiceHtml = choices.length
      ? `<ol class="generated-choice-list" type="A">${choices.map(choice => `<li>${escapeHtml(choice)}</li>`).join("")}</ol>`
      : `<p class="muted-text">Answer: ________________________________</p>`;
    return `
      <div class="generated-question">
        <div class="generated-question-title"><span class="question-number">${index + 1}.</span><div class="question-body">${renderQuizContent(q.question)}</div></div>
        ${choiceHtml}
      </div>`;
  }).join("");

  const answerHtml = questions.map((q, index) => `
    <div class="answer-key-item">
      <strong>${index + 1}. Answer:</strong> ${escapeHtml(q.displayAnswer || q.answer || "")}<br>
      <small><strong>Explanation:</strong> ${escapeHtml(q.explanation || "No explanation provided.")}</small>
    </div>
  `).join("");

  return `
    <div class="generated-quiz-paper">
      <div class="generated-quiz-header">
        <h2>${escapeHtml(settings.title)}</h2>
      </div>
      <div class="generated-quiz-info">
        <div><strong>Name:</strong> ________________________________</div>
        <div><strong>Date:</strong> ________________________________</div>
        <div><strong>Topics:</strong> ${escapeHtml(settings.topicLabel)}</div>
        <div><strong>Items:</strong> ${questions.length}</div>
      </div>
      ${showQuestions ? `<div class="question-section">${questionHtml}</div>` : ""}
      ${showAnswers ? `<div class="answer-key-box"><h3>Answer Key and Explanations</h3>${answerHtml}</div>` : ""}
    </div>
  `;
}

function generateAdminPdfQuiz() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");

  const selectedTopics = getAdminPdfSelectedValues("adminPdfTopic");
  const selectedDifficulties = getAdminPdfSelectedValues("adminPdfDifficulty");
  const type = document.getElementById("adminPdfQuizType")?.value || "mixed";
  const count = Math.max(1, Number(document.getElementById("adminPdfItemCount")?.value || 10));
  const title = document.getElementById("adminPdfQuizTitle")?.value.trim() || "FAR Practice Quiz";
  const includeMode = document.getElementById("adminPdfIncludeAnswers")?.value || "questions-only";

  let filtered = quizBank.filter(q => {
    const topicMatch = selectedTopics.includes("all") || selectedTopics.includes(q.topic);
    const difficultyMatch = selectedDifficulties.includes("all") || selectedDifficulties.includes(q.difficulty);
    const typeMatch = type === "mixed" || q.type === type;
    const approvedMatch = (q.reviewStatus || "approved") === "approved";
    return topicMatch && difficultyMatch && typeMatch && approvedMatch;
  });

  filtered = shuffleArray(filtered).slice(0, count).map(hydrateQuestion);
  const preview = document.getElementById("adminGeneratedQuizPreview");
  const message = document.getElementById("adminPdfQuizMessage");

  if (!filtered.length) {
    if (preview) preview.innerHTML = "";
    if (message) { message.textContent = "No approved questions found for the selected filters."; message.className = "form-message error"; }
    return;
  }

  const topicLabel = selectedTopics.includes("all") ? "All Topics" : selectedTopics.map(getTopicTitle).join(", ");
  if (preview) preview.innerHTML = buildPrintableQuizHtml(filtered, { title, includeMode, topicLabel });
  if (message) { message.textContent = `Generated ${filtered.length} item(s). Click Convert / Save as PDF to print or save the quiz as a PDF.`; message.className = "form-message success"; }
}

function printAdminGeneratedQuiz() {
  const preview = document.getElementById("adminGeneratedQuizPreview");
  if (!preview || !preview.innerHTML.trim()) {
    alert("Please generate a quiz preview first.");
    return;
  }
  window.print();
}

function clearAdminGeneratedQuiz() {
  const preview = document.getElementById("adminGeneratedQuizPreview");
  const message = document.getElementById("adminPdfQuizMessage");
  if (preview) preview.innerHTML = "";
  if (message) { message.textContent = ""; message.className = "form-message"; }
}



function populateQuestionRepositoryFilters() {
  const topicFilter = document.getElementById("repoTopicFilter");
  if (topicFilter) {
    const current = topicFilter.value || "all";
    topicFilter.innerHTML = `<option value="all">All Topics</option>` + topics.map(topic =>
      `<option value="${escapeHtml(topic.id)}">${escapeHtml(topic.title)}</option>`
    ).join("");
    topicFilter.value = [...topicFilter.options].some(option => option.value === current) ? current : "all";
  }
}

async function loadQuestionRepository() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  if (API_BASE_URL) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/admin/quizzes`, { headers: getAuthHeaders() });
      if (response.ok) quizBank = await response.json();
    } catch (error) {
      console.warn("Unable to load question repository from backend.", error);
    }
  }
  populateQuestionRepositoryFilters();
  renderQuestionRepository();
}

function getQuestionRepositoryFiltered() {
  const search = (document.getElementById("repoSearchInput")?.value || "").trim().toLowerCase();
  const topic = document.getElementById("repoTopicFilter")?.value || "all";
  const type = document.getElementById("repoTypeFilter")?.value || "all";
  const difficulty = document.getElementById("repoDifficultyFilter")?.value || "all";
  const status = document.getElementById("repoStatusFilter")?.value || "all";

  return quizBank.filter(q => {
    const haystack = [
      q.question,
      q.answer,
      q.explanation,
      q.solutionTemplate,
      q.answerExpression,
      q.adminNotes,
      getTopicTitle(q.topic),
      ...(Array.isArray(q.choices) ? q.choices : [])
    ].join(" ").toLowerCase();
    return (!search || haystack.includes(search))
      && (topic === "all" || q.topic === topic)
      && (type === "all" || q.type === type)
      && (difficulty === "all" || q.difficulty === difficulty)
      && (status === "all" || (q.reviewStatus || "approved") === status);
  });
}

function renderQuestionRepository() {
  const list = document.getElementById("questionRepositoryList");
  const summary = document.getElementById("questionRepositorySummary");
  if (!list) return;

  const filtered = getQuestionRepositoryFiltered();
  const counts = quizBank.reduce((acc, q) => {
    const status = q.reviewStatus || "approved";
    acc.total += 1;
    acc[status] = (acc[status] || 0) + 1;
    acc.theory += q.type === "theory" ? 1 : 0;
    acc.problem += q.type === "problem" ? 1 : 0;
    return acc;
  }, { total: 0, approved: 0, pending_review: 0, needs_revision: 0, theory: 0, problem: 0 });

  if (summary) {
    summary.innerHTML = `
      <div class="summary-pill">Total: <strong>${counts.total}</strong></div>
      <div class="summary-pill">Showing: <strong>${filtered.length}</strong></div>
      <div class="summary-pill approved">Approved: <strong>${counts.approved || 0}</strong></div>
      <div class="summary-pill pending_review">Pending: <strong>${counts.pending_review || 0}</strong></div>
      <div class="summary-pill needs_revision">Revision: <strong>${counts.needs_revision || 0}</strong></div>
      <div class="summary-pill">Theory: <strong>${counts.theory}</strong></div>
      <div class="summary-pill">Problem: <strong>${counts.problem}</strong></div>
    `;
  }

  if (!filtered.length) {
    list.innerHTML = `<p>No questions found in the repository for the selected filters.</p>`;
    return;
  }

  const grouped = filtered.reduce((acc, q) => {
    const key = q.topic || "uncategorized";
    if (!acc[key]) acc[key] = [];
    acc[key].push(q);
    return acc;
  }, {});

  const orderedTopics = [
    ...topics.map(topic => topic.id),
    ...Object.keys(grouped).filter(topicId => !topics.some(topic => topic.id === topicId))
  ].filter(topicId => grouped[topicId]);

  list.innerHTML = orderedTopics.map(topicId => `
    <section class="repository-topic-group">
      <div class="repository-topic-header">
        <h4>${escapeHtml(getTopicTitle(topicId))}</h4>
        <span>${grouped[topicId].length} question(s)</span>
      </div>
      ${grouped[topicId].map((q, index) => renderRepositoryQuestionCard(q, index)).join("")}
    </section>
  `).join("");
}

function renderRepositoryQuestionCard(q, index) {
  const status = q.reviewStatus || "approved";
  const choices = Array.isArray(q.choices) && q.choices.length
    ? `<ol type="A" class="repository-choice-list">${q.choices.map(choice => `<li>${renderAccountingContent(choice)}</li>`).join("")}</ol>`
    : `<p class="muted-text">No choices / problem-solving answer field.</p>`;
  const answer = q.answerFormula
    ? `${q.answerFormula}${q.answerExpression ? `: ${q.answerExpression}` : ""}`
    : (q.answer || "No answer saved");
  return `
    <article class="repository-card">
      <div class="repository-card-head">
        <div>
          <span class="tag">${escapeHtml(q.type === "problem" ? "Problem Solving" : "Theory")}</span>
          <span class="status-badge ${status}">${escapeHtml(status.replace(/_/g, " "))}</span>
          <span class="tag muted-tag">${escapeHtml(q.difficulty || "")}</span>
        </div>
        <small>ID: ${escapeHtml(q.id || `question-${index}`)}</small>
      </div>
      <div class="repository-question-text">${renderAccountingContent(q.question)}</div>
      <div class="repository-two-col">
        <div><strong>Choices</strong>${choices}</div>
        <div><strong>Answer / Formula</strong><p>${escapeHtml(answer)}</p></div>
      </div>
      <details>
        <summary>View explanation, variables, and metadata</summary>
        <div class="repository-details">
          <strong>Explanation / Solution</strong>
          <div>${renderAccountingContent(q.solutionTemplate || q.explanation || "")}</div>
          ${q.variables ? `<strong>Variable Settings</strong><pre>${escapeHtml(JSON.stringify(q.variables, null, 2))}</pre>` : ""}
          <p><strong>Created By:</strong> ${escapeHtml(q.createdBy || "")}</p>
          <p><strong>Created At:</strong> ${escapeHtml(q.createdAt || "")}</p>
          <p><strong>Reviewed By:</strong> ${escapeHtml(q.reviewedBy || "")}</p>
        </div>
      </details>
      <div class="button-row compact-row">
        <button class="btn secondary small-btn" type="button" onclick="setQuestionStatus('${escapeJs(q.id)}', 'approved'); setTimeout(renderQuestionRepository, 100);">Approve</button>
        <button class="btn ghost small-btn" type="button" onclick="setQuestionStatus('${escapeJs(q.id)}', 'needs_revision'); setTimeout(renderQuestionRepository, 100);">Needs Revision</button>
        <button class="btn ghost small-btn" type="button" onclick="duplicateRepositoryQuestion('${escapeJs(q.id)}')">Duplicate</button>
        <button class="btn danger-btn small-btn" type="button" onclick="deleteQuestion('${escapeJs(q.id)}'); setTimeout(renderQuestionRepository, 100);">Delete</button>
      </div>
    </article>
  `;
}

async function duplicateRepositoryQuestion(questionId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const source = quizBank.find(q => q.id === questionId);
  if (!source) return alert("Question not found.");
  const duplicate = {
    ...JSON.parse(JSON.stringify(source)),
    id: crypto.randomUUID ? crypto.randomUUID() : `q-${Date.now()}`,
    question: `${source.question} ${source.question.includes("(Copy)") ? "" : "(Copy)"}`.trim(),
    reviewStatus: "pending_review",
    adminNotes: "Duplicated from Question Repository.",
    createdBy: currentUser.email,
    createdAt: new Date().toISOString(),
    reviewedBy: undefined,
    reviewedAt: undefined,
    updatedAt: undefined
  };

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/quizzes`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(duplicate)
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to duplicate question.");
    quizBank.push(data);
  } else {
    quizBank.push(duplicate);
  }
  await saveData();
  renderQuestionRepository();
  renderAdminQuizReview();
  alert("Question duplicated and marked as Pending Review.");
}

function exportQuestionRepository() {
  const payload = {
    exportedAt: new Date().toISOString(),
    questionCount: quizBank.length,
    questions: quizBank
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `question-repository-${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

async function importQuestionRepository(event) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const file = event.target.files?.[0];
  if (!file) return;
  try {
    const text = await file.text();
    const parsed = JSON.parse(text);
    const imported = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.questions) ? parsed.questions : []);
    if (!imported.length) return alert("No questions found in the selected JSON file.");
    if (!confirm(`Import ${imported.length} question(s) into the repository? Imported questions will be marked Pending Review.`)) return;

    let added = 0;
    for (const item of imported) {
      const question = {
        ...item,
        id: crypto.randomUUID ? crypto.randomUUID() : `q-${Date.now()}-${added}`,
        topic: item.topic || topics[0]?.id || "general",
        type: item.type === "problem" ? "problem" : "theory",
        difficulty: ["easy", "medium", "hard"].includes(item.difficulty) ? item.difficulty : "easy",
        choices: Array.isArray(item.choices) ? item.choices : [],
        reviewStatus: "pending_review",
        createdBy: currentUser.email,
        createdAt: new Date().toISOString()
      };
      if (!question.question || !question.explanation || (!question.answerFormula && !question.answer)) continue;

      if (API_BASE_URL) {
        const response = await fetch(`${API_BASE_URL}/api/quizzes`, {
          method: "POST",
          headers: { "Content-Type": "application/json", ...getAuthHeaders() },
          body: JSON.stringify(question)
        });
        if (response.ok) {
          quizBank.push(await response.json());
          added += 1;
        }
      } else {
        quizBank.push(question);
        added += 1;
      }
    }
    await saveData();
    renderQuestionRepository();
    renderAdminQuizReview();
    alert(`${added} question(s) imported successfully.`);
  } catch (error) {
    alert("Invalid JSON file. Please upload a valid Question Repository export.");
  } finally {
    event.target.value = "";
  }
}

function showAdminSection(sectionId) {
  document.querySelectorAll(".admin-section-panel").forEach(panel => panel.classList.remove("active-admin-section"));
  const selected = document.getElementById(sectionId);
  if (selected) selected.classList.add("active-admin-section");
  const dropdown = document.getElementById("adminFeatureSelect");
  if (dropdown) dropdown.value = sectionId;
  if (sectionId === "admin-overview") renderAdminOverview();
  if (sectionId === "admin-review-quizzer") loadAdminQuizBank();
  if (sectionId === "admin-question-repository") loadQuestionRepository();
  if (sectionId === "admin-generate-pdf-quiz") setupAdminPdfQuizOptions();
  if (sectionId === "admin-generate-pdf") {
    populateAdminPdfTopicChoices();
    setupAdminPdfDifficultyCheckboxes();
  }
  if (sectionId === "admin-account-access") {
    loadStudentsForAdmin();
  }
  if (sectionId === "admin-professor-profile") loadProfessorEditor();
  if (sectionId === "admin-site-settings") loadSiteSettingsEditor();
  if (sectionId === "admin-scores") loadStudentScores();
  if (sectionId === "admin-payments") loadPaymentRequestsForAdmin();
  if (sectionId === "admin-student-view") renderStudentViewPreview("dashboard");
}


function getAllLocalUsersForAdminOverview() {
  const demo = JSON.parse(localStorage.getItem("farDemoUsers") || "[]");
  const registered = JSON.parse(localStorage.getItem("farUsers") || "[]");
  const merged = [...demo, ...registered];
  const seen = new Set();
  return merged.filter(user => {
    const key = (user.id || user.email || "").toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function getAllQuizHistoryForAdminOverview() {
  return JSON.parse(localStorage.getItem("farQuizHistory") || "[]");
}

function buildAdminOverviewData() {
  const users = getAllLocalUsersForAdminOverview();
  const students = users.filter(user => user.role === "student");
  const payments = getLocalPaymentRequests ? getLocalPaymentRequests() : [];
  const scores = getAllQuizHistoryForAdminOverview();
  const todayKey = new Date().toISOString().slice(0, 10);
  const approvedPaymentsToday = payments.filter(p => (p.status === "approved" || p.status === "received") && String(p.approvedAt || p.createdAt || "").slice(0, 10) === todayKey);
  const creditsAddedToday = approvedPaymentsToday.reduce((sum, p) => sum + Number(p.creditsAdded || p.itemCount || p.creditsApplied || 0), 0);

  return {
    students,
    payments,
    scores,
    totalStudents: students.length,
    pendingRegistrations: students.filter(s => (s.approvalStatus || "approved") === "pending_approval").length,
    approvedStudents: students.filter(s => (s.approvalStatus || "approved") === "approved").length,
    expiredStudents: students.filter(s => (s.approvalStatus || "approved") === "approved" && !getTrialStatus(s).active).length,
    zeroCreditStudents: students.filter(s => Number(s.quizCredits || 0) <= 0).length,
    pendingPayments: payments.filter(p => (p.status || "pending") === "pending").length,
    approvedPaymentsToday: approvedPaymentsToday.length,
    creditsAddedToday,
    pendingQuestions: quizBank.filter(q => (q.status || "pending") === "pending" || (q.reviewStatus || "pending") === "pending").length,
    needsRevisionQuestions: quizBank.filter(q => (q.status || q.reviewStatus) === "needs_revision").length,
    totalQuestions: quizBank.length,
    quizAttempts: scores.length
  };
}

function renderAdminSummaryCards(data) {
  const box = document.getElementById("adminSummaryCards");
  if (!box) return;
  const cards = [
    ["Total Students", data.totalStudents],
    ["Pending Registrations", data.pendingRegistrations],
    ["Approved Students", data.approvedStudents],
    ["Expired Students", data.expiredStudents],
    ["Pending Payments", data.pendingPayments],
    ["Pending Questions", data.pendingQuestions],
    ["Total Questions", data.totalQuestions],
    ["Quiz Attempts", data.quizAttempts]
  ];
  box.innerHTML = cards.map(([label, value]) => `<div class="summary-card"><span>${escapeHtml(label)}</span><strong>${Number(value || 0)}</strong></div>`).join("");
}

function renderAdminNeedsAction(data) {
  const box = document.getElementById("adminNeedsAction");
  if (!box) return;
  const actions = [
    { count: data.pendingRegistrations, text: "student registration(s) need approval", button: "Review", target: "admin-account-access" },
    { count: data.pendingPayments, text: "payment request(s) need verification", button: "Check", target: "admin-payments" },
    { count: data.pendingQuestions, text: "quiz question(s) need review", button: "Review", target: "admin-review-quizzer" },
    { count: data.expiredStudents, text: "student(s) have expired access", button: "Manage", target: "admin-account-access" }
  ].filter(item => item.count > 0);
  box.innerHTML = actions.length ? actions.map(item => `
    <div class="need-action-item">
      <div><strong>${item.count}</strong> ${escapeHtml(item.text)}</div>
      <button class="btn small-btn secondary" onclick="showAdminSection('${item.target}')">${escapeHtml(item.button)}</button>
    </div>`).join("") : `<p class="muted-text">No urgent action right now.</p>`;
}

function renderAdminPerformanceSnapshot(data) {
  const box = document.getElementById("adminPerformanceSnapshot");
  if (!box) return;
  const scores = data.scores || [];
  if (!scores.length) {
    box.innerHTML = `<p class="muted-text">No student quiz attempts yet.</p>`;
    return;
  }
  const avg = Math.round(scores.reduce((sum, s) => sum + Number(s.percentage || 0), 0) / scores.length);
  const topicStats = {};
  scores.forEach(score => (score.reviewItems || []).forEach(item => {
    const topic = item.topic || "Unassigned";
    topicStats[topic] = topicStats[topic] || { correct: 0, total: 0 };
    topicStats[topic].total += 1;
    if (item.isCorrect) topicStats[topic].correct += 1;
  }));
  const topicRows = Object.entries(topicStats).map(([topicId, stat]) => {
    const topic = topics.find(t => t.id === topicId)?.title || topicId;
    const pct = stat.total ? Math.round((stat.correct / stat.total) * 100) : 0;
    return { topic, pct };
  }).sort((a, b) => a.pct - b.pct);
  const weakest = topicRows[0]?.topic || "Not enough data";
  const strongest = topicRows[topicRows.length - 1]?.topic || "Not enough data";
  box.innerHTML = `
    <div class="dashboard-mini-item"><span>Class Average</span><strong>${avg}%</strong></div>
    <div class="dashboard-mini-item"><span>Weakest Topic</span><strong>${escapeHtml(weakest)}</strong></div>
    <div class="dashboard-mini-item"><span>Strongest Topic</span><strong>${escapeHtml(strongest)}</strong></div>
  `;
}

function renderAdminPaymentCreditSnapshot(data) {
  const box = document.getElementById("adminPaymentCreditSnapshot");
  if (!box) return;
  box.innerHTML = `
    <div class="dashboard-mini-item"><span>Pending Payments</span><strong>${data.pendingPayments}</strong></div>
    <div class="dashboard-mini-item"><span>Approved Payments Today</span><strong>${data.approvedPaymentsToday}</strong></div>
    <div class="dashboard-mini-item"><span>Credits Added Today</span><strong>${data.creditsAddedToday}</strong></div>
    <div class="dashboard-mini-item"><span>Students with Zero Credits</span><strong>${data.zeroCreditStudents}</strong></div>
  `;
}

function setAdminHealthSubject(subjectId) {
  adminHealthSubject = String(subjectId || "FAR").toUpperCase();
  renderAdminQuestionBankHealth(buildAdminOverviewData());
}

function renderAdminQuestionBankHealth(data) {
  const box = document.getElementById("adminQuestionBankHealth");
  if (!box) return;
  const availableSubjects = SUBJECTS.filter(subject => topics.some(topic => (topic.subject || "FAR") === subject.id));
  if (!availableSubjects.some(subject => subject.id === adminHealthSubject)) {
    adminHealthSubject = availableSubjects[0]?.id || "FAR";
  }

  const selectedSubject = adminHealthSubject;
  const subjectName = SUBJECTS.find(subject => subject.id === selectedSubject)?.name || selectedSubject;
  const filteredTopics = topics.filter(topic => (topic.subject || "FAR") === selectedSubject);
  const rows = filteredTopics.map(topic => {
    const related = quizBank.filter(q => q.topic === topic.id);
    const approved = related.filter(q => (q.status || q.reviewStatus) === "approved").length;
    const pending = related.filter(q => (q.status || "pending") === "pending" || (q.reviewStatus || "pending") === "pending").length;
    const revision = related.filter(q => (q.status || q.reviewStatus) === "needs_revision").length;
    const difficultProblem = related.filter(q => (q.status || q.reviewStatus) === "approved" && q.type === "problem" && (q.difficulty === "hard" || q.difficulty === "difficult")).length;
    return { topic: topic.title, approved, pending, revision, total: related.length, difficultProblem };
  });

  const totals = rows.reduce((acc, row) => {
    acc.approved += row.approved;
    acc.pending += row.pending;
    acc.revision += row.revision;
    acc.total += row.total;
    return acc;
  }, { approved: 0, pending: 0, revision: 0, total: 0 });

  const warnings = rows
    .filter(r => r.total > 0 && r.difficultProblem < 3)
    .map(r => `${escapeHtml(r.topic)} has only ${r.difficultProblem} approved difficult problem-solving question(s).`);

  box.innerHTML = `
    <div class="health-filter-row">
      <label for="adminHealthSubjectSelect"><strong>Subject</strong></label>
      <select id="adminHealthSubjectSelect" onchange="setAdminHealthSubject(this.value)">
        ${availableSubjects.map(subject => `<option value="${subject.id}" ${subject.id === selectedSubject ? "selected" : ""}>${escapeHtml(subject.id)} - ${escapeHtml(subject.name)}</option>`).join("")}
      </select>
    </div>
    <div class="health-summary-strip">
      <span><strong>${escapeHtml(selectedSubject)}</strong> — ${escapeHtml(subjectName)}</span>
      <span>Approved: <strong>${totals.approved}</strong></span>
      <span>Pending: <strong>${totals.pending}</strong></span>
      <span>Needs Revision: <strong>${totals.revision}</strong></span>
      <span>Total: <strong>${totals.total}</strong></span>
    </div>
    <table class="admin-health-table">
      <thead><tr><th>Topic</th><th>Approved</th><th>Pending</th><th>Needs Revision</th><th>Total</th></tr></thead>
      <tbody>${rows.map(r => `<tr><td>${escapeHtml(r.topic)}</td><td>${r.approved}</td><td>${r.pending}</td><td>${r.revision}</td><td>${r.total}</td></tr>`).join("") || `<tr><td colspan="5" class="muted-text">No topics found for this subject.</td></tr>`}</tbody>
    </table>
    ${warnings.length ? `<div class="bank-warning"><strong>Question Bank Warning:</strong><br>${warnings.slice(0, 3).join("<br>")}</div>` : ""}
  `;
}


function renderAdminRecentActivity(data) {
  const box = document.getElementById("adminRecentActivity");
  if (!box) return;
  const activities = [];
  data.students.forEach(student => {
    if (student.createdAt) activities.push({ date: student.createdAt, text: `${student.name || student.email} registered.` });
    if (student.approvedAt) activities.push({ date: student.approvedAt, text: `${student.name || student.email} was approved.` });
  });
  data.payments.forEach(payment => {
    activities.push({ date: payment.createdAt || payment.submittedAt || new Date().toISOString(), text: `${payment.name || payment.email || "Student"} submitted a payment request for ${payment.itemCount || payment.creditsAdded || 0} item(s).` });
    if (payment.approvedAt) activities.push({ date: payment.approvedAt, text: `Payment approved for ${payment.name || payment.email || "student"}.` });
  });
  data.scores.forEach(score => activities.push({ date: score.createdAt, text: `${score.studentName || score.studentEmail || "Student"} completed a ${score.total || 0}-item quiz.` }));
  const sorted = activities.filter(a => a.date).sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 6);
  box.innerHTML = sorted.length ? sorted.map(a => `
    <div class="activity-item">
      <span>${escapeHtml(a.text)}</span>
      <small>${new Date(a.date).toLocaleString()}</small>
    </div>`).join("") : `<p class="muted-text">No recent activity yet.</p>`;
}

function renderAdminAnnouncementPreview() {
  const box = document.getElementById("adminAnnouncementPreview");
  if (!box) return;
  box.innerHTML = renderAccountingContent(siteSettings.announcement || "No student announcement yet.");
}

function renderAdminOverview() {
  if (currentUser?.role !== "admin") return;
  const data = buildAdminOverviewData();
  renderAdminSummaryCards(data);
  renderAdminNeedsAction(data);
  renderAdminPerformanceSnapshot(data);
  renderAdminPaymentCreditSnapshot(data);
  renderAdminQuestionBankHealth(data);
  renderAdminRecentActivity(data);
  renderAdminAnnouncementPreview();
}

function renderProfessorProfile() {
  const setText = (id, value) => {
    const el = document.getElementById(id);
    if (el) el.textContent = value || "";
  };
  setText("professorNameText", professorProfile.name);
  setText("professorPositionText", professorProfile.position);
  setText("professorSubjectText", professorProfile.subject);
  setText("professorEmailText", professorProfile.email);
  setText("professorHoursText", professorProfile.consultationHours);
  setText("professorPhilosophyText", professorProfile.philosophy);

  const photoBoxes = [document.getElementById("professorPhotoPreview"), document.getElementById("editProfessorPhotoPreview")].filter(Boolean);
  photoBoxes.forEach(box => {
    if (professorProfile.photoData) {
      box.innerHTML = `<img src="${professorProfile.photoData}" alt="Professor profile photo">`;
    } else {
      box.textContent = professorProfile.photoLabel || "Photo";
    }
  });
}

function loadProfessorEditor() {
  renderProfessorProfile();
  const fields = {
    editProfessorName: professorProfile.name,
    editProfessorPosition: professorProfile.position,
    editProfessorSubject: professorProfile.subject,
    editProfessorEmail: professorProfile.email,
    editProfessorHours: professorProfile.consultationHours,
    editProfessorPhilosophy: professorProfile.philosophy,
    editProfessorPhoto: professorProfile.photoLabel
  };
  Object.entries(fields).forEach(([id, value]) => {
    const el = document.getElementById(id);
    if (el) el.value = value || "";
  });
}

async function saveProfessorProfile() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  professorProfile = {
    name: document.getElementById("editProfessorName").value.trim() || "Professor Name",
    position: document.getElementById("editProfessorPosition").value.trim() || "Professor / Instructor",
    subject: document.getElementById("editProfessorSubject").value.trim() || "Multi-Subject CPA Review",
    email: document.getElementById("editProfessorEmail").value.trim() || "professor@email.com",
    consultationHours: document.getElementById("editProfessorHours").value.trim() || "Monday to Friday, 3:00 PM – 5:00 PM",
    philosophy: document.getElementById("editProfessorPhilosophy").value.trim() || "To help students understand accounting concepts through clear discussions, practical computations, and interactive assessment.",
    photoLabel: document.getElementById("editProfessorPhoto").value.trim() || "Photo",
    photoData: professorProfile.photoData || ""
  };

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/professor-profile`, {
      method: "PUT",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify(professorProfile)
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to save professor profile.");
    professorProfile = { ...professorProfile, ...data };
  }

  await saveData();
  renderProfessorProfile();
  alert("Professor profile saved successfully.");
}

function handleProfessorPhotoUpload(event) {
  const file = event.target.files?.[0];
  if (!file) return;
  const validTypes = ["image/jpeg", "image/jpg"];
  const isJpeg = validTypes.includes(file.type) || /\.jpe?g$/i.test(file.name);
  if (!isJpeg) {
    alert("Please upload JPG or JPEG only.");
    event.target.value = "";
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    professorProfile.photoData = reader.result;
    renderProfessorProfile();
  };
  reader.readAsDataURL(file);
}

function removeProfessorPhoto() {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  professorProfile.photoData = "";
  const input = document.getElementById("editProfessorPhotoFile");
  if (input) input.value = "";
  renderProfessorProfile();
}


async function addQuizCredits(userId) {
  return addQuizCreditsFromInput(userId, "credits-");
}

async function addQuizCreditsFromInput(userId, prefix = "credits-") {
  const input = document.getElementById(`${prefix}${userId}`);
  if (!input) return alert("Quiz credits input not found.");
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const credits = Number(input.value);
  if (!credits || credits <= 0) return alert("Enter valid number of quiz credits.");

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/add-quiz-credits`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ credits })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add quiz credits.");
    alert(data.message || `${credits} quiz credit(s) added.`);
  } else {
    const updated = updateLocalUserCredits(userId, credits);
    if (!updated) return alert("Student not found.");
    alert(`${credits} quiz credit(s) added to ${updated.name || updated.email}.`);
  }

  await loadStudentsForAdmin();
  await loadManualCreditStudents();
}

async function addTrialDaysFromInput(userId, prefix = "days-") {
  const input = document.getElementById(`${prefix}${userId}`);
  if (!input) return alert("Trial days input not found.");
  if (prefix === "days-") return addTrialDays(userId);
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const days = Number(input.value);
  if (!days || days <= 0) return alert("Enter valid number of days.");

  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/add-trial-days`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ days })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add days.");
  } else {
    for (const key of ["farDemoUsers", "farUsers"]) {
      const users = JSON.parse(localStorage.getItem(key) || "[]");
      const user = users.find(u => (u.id || u.email) === userId);
      if (user && user.role === "student") {
        const base = user.trialEndDate && new Date(user.trialEndDate) > new Date() ? new Date(user.trialEndDate) : new Date();
        user.trialEndDate = addDays(base, days).toISOString();
        user.trialDays = Number(user.trialDays || 30) + days;
        localStorage.setItem(key, JSON.stringify(users));
      }
    }
  }
  await loadStudentsForAdmin();
  alert(`${days} trial day(s) added.`);
}


async function addSubjectSubscription(userId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const subject = document.getElementById(`sub-subject-${userId}`)?.value || "FAR";
  const months = Math.max(1, Number(document.getElementById(`sub-months-${userId}`)?.value || 1));
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/add-subscription`, {
      method: "POST", headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ planType: "per_subject", subject, months })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add subscription.");
    alert(data.message || `${subject} subscription added.`);
  } else {
    const user = activateLocalSubscription(userId, "per_subject", [subject], months);
    if (!user) return alert("Student not found.");
    alert(`${subject} subscription added for ${months} month(s).`);
  }
  await loadStudentsForAdmin();
}

async function addAllSubjectsSubscription(userId) {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const months = Math.max(1, Number(document.getElementById(`sub-months-${userId}`)?.value || 1));
  if (API_BASE_URL) {
    const response = await fetch(`${API_BASE_URL}/api/admin/users/${encodeURIComponent(userId)}/add-subscription`, {
      method: "POST", headers: { "Content-Type": "application/json", ...getAuthHeaders() },
      body: JSON.stringify({ planType: "all_subjects", months })
    });
    const data = await response.json();
    if (!response.ok) return alert(data.error || "Unable to add all-subject subscription.");
    alert(data.message || "All Subjects subscription added.");
  } else {
    const user = activateLocalSubscription(userId, "all_subjects", [], months);
    if (!user) return alert("Student not found.");
    alert(`All Subjects subscription added for ${months} month(s).`);
  }
  await loadStudentsForAdmin();
}

async function loadStudentScores() {
  const box = document.getElementById("scoresList");
  if (!box || currentUser?.role !== "admin") return;
  if (!API_BASE_URL) {
    box.innerHTML = `<p class="muted-text">Student score viewing requires the deployed backend because GitHub Pages does not store central class records.</p>`;
    return;
  }
  try {
    const response = await fetch(`${API_BASE_URL}/api/scores`, { headers: getAuthHeaders() });
    const scores = await response.json();
    if (!response.ok) throw new Error(scores.error || "Unable to load scores.");
    box.innerHTML = scores.slice().reverse().map(score => `
      <div class="score-row">
        <div><strong>${escapeHtml(score.email || score.userEmail || "Student")}</strong><br><small>${new Date(score.createdAt || score.date || Date.now()).toLocaleString()}</small></div>
        <div><strong>${score.score}/${score.total}</strong><br><small>${score.percentage}%</small></div>
      </div>
    `).join("") || "<p>No scores submitted yet.</p>";
  } catch (error) {
    box.innerHTML = `<p class="form-message error">${escapeHtml(error.message)}</p>`;
  }
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadData();
  renderTopics();
  populateSelects();
  setupAdminPdfQuizOptions();
  setupQuizTopicCheckboxes();
  setupDifficultyCheckboxes();
  renderProfessorProfile();
  loadProfessorEditor();
  loadSiteSettingsEditor();
  renderStudentHome();

  updateAuthUI();
  document.getElementById("quizForm").addEventListener("submit", generateQuiz);
  document.getElementById("loginForm").addEventListener("submit", async event => {
    event.preventDefault();
    try {
      const user = await loginUser(document.getElementById("loginEmail").value.trim(), document.getElementById("loginPassword").value);
      currentUser = user;
      localStorage.setItem("farCurrentUser", JSON.stringify(user));
      await loadData();
      renderTopics();
      populateSelects();
      setMessage("loginMessage", "Login successful.", "success");
      updateAuthUI();
      showPage(user.role === "admin" ? "admin" : "student");
    } catch (error) { setMessage("loginMessage", error.message, "error"); }
  });
  const sendOtpBtn = document.getElementById("sendOtpBtn");
  if (sendOtpBtn) sendOtpBtn.addEventListener("click", async () => {
    try {
      const data = await sendRegistrationOtp(
        document.getElementById("registerName").value.trim(),
        document.getElementById("registerContact").value.trim(),
        document.getElementById("registerEmail").value.trim(),
        document.getElementById("registerPassword").value
      );
      document.getElementById("otpBox").classList.remove("hidden-by-role");
      const preview = document.getElementById("otpPreviewText");
      if (preview) preview.textContent = "OTP sent to your email. Please check your inbox or spam folder.";
      setMessage("registerMessage", data.message || "OTP sent to your email. Please enter the OTP to complete registration.", "success");
    } catch (error) { setMessage("registerMessage", error.message, "error"); }
  });

  document.getElementById("registerForm").addEventListener("submit", async event => {
    event.preventDefault();
    try {
      const user = await registerUser(
        document.getElementById("registerName").value.trim(),
        document.getElementById("registerContact").value.trim(),
        document.getElementById("registerEmail").value.trim(),
        document.getElementById("registerPassword").value,
        document.getElementById("registerOtp").value.trim(),
        "student"
      );
      setMessage("registerMessage", `Registration submitted for ${user.name || user.email}. Please wait for admin approval before logging in.`, "success");
      event.target.reset();
      document.getElementById("otpBox").classList.add("hidden-by-role");
    } catch (error) { setMessage("registerMessage", error.message, "error"); }
  });
  document.getElementById("editTopicSelect").addEventListener("change", loadTopicEditor);
  const photoInput = document.getElementById("editProfessorPhotoFile");
  if (photoInput) photoInput.addEventListener("change", handleProfessorPhotoUpload);
  const lessonSelect = document.getElementById("lessonTabTopicSelect");
  if (lessonSelect) lessonSelect.addEventListener("change", renderLessonTabsList);
  ["reviewTopicFilter", "reviewTypeFilter", "reviewStatusFilter"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("change", renderAdminQuizReview);
  });

  document.querySelectorAll(".nav-link").forEach(link => {
    link.addEventListener("click", event => {
      const target = link.getAttribute("href").replace("#", "");
      if (document.getElementById(target)) {
        event.preventDefault();
        showPage(target);
        document.getElementById("navMenu").classList.remove("open");
      }
    });
  });

  document.getElementById("menuBtn").addEventListener("click", () => {
    document.getElementById("navMenu").classList.toggle("open");
  });
});


document.addEventListener("DOMContentLoaded", () => { if (typeof updateAdvancedQuizTotals === "function") updateAdvancedQuizTotals(); });


/* Subject background/theme switcher for student experience */
const SUBJECT_THEME_CLASS_LIST = ["far", "afar", "mas", "tax", "rfbt", "aud"].map(s => `subject-theme-${s}`);
function getSubjectTheme(subjectId) {
  const subject = SUBJECTS.find(s => String(s.id).toUpperCase() === String(subjectId).toUpperCase());
  return subject?.theme || "blue";
}
function clearSubjectTheme() {
  document.body.classList.remove(...SUBJECT_THEME_CLASS_LIST);
  document.body.removeAttribute("data-active-subject");
}
function applySubjectTheme(subjectId) {
  if (!subjectId || subjectId === "all") {
    clearSubjectTheme();
    return;
  }
  clearSubjectTheme();
  const themeClass = `subject-theme-${String(subjectId).toLowerCase()}`;
  document.body.classList.add(themeClass);
  document.body.setAttribute("data-active-subject", String(subjectId).toUpperCase());
}
function handleSubjectFilterChange() {
  const select = document.getElementById("subjectFilter");
  const value = select?.value || "all";
  applySubjectTheme(value);
  renderTopics();
}
function selectSubject(subjectId) {
  const select = document.getElementById("subjectFilter");
  if (select) select.value = subjectId;
  applySubjectTheme(subjectId);
  renderTopics();
}
function navigateToSubject(subjectId) {
  const subject = String(subjectId || "FAR").toUpperCase();
  const select = document.getElementById("subjectFilter");
  if (select) select.value = subject;
  applySubjectTheme(subject);
  showPage("topics");
  renderTopics();
  const title = document.querySelector("#topics .section-title");
  if (title) title.scrollIntoView({ behavior: "smooth", block: "start" });
}
function subjectChipRow(activeSubject = "all") {
  const chips = [`<button type="button" class="subject-chip ${activeSubject === "all" ? "active-subject" : ""}" onclick="selectSubject('all')">All Subjects</button>`]
    .concat(SUBJECTS.map(s => `<button type="button" class="subject-chip ${activeSubject === s.id ? "active-subject" : ""}" onclick="selectSubject('${s.id}')">${s.id}</button>`));
  return `<div class="subject-chip-row">${chips.join("")}</div>`;
}

/* Override topics rendering to filter by subject and change background color */
function renderTopics() {
  const grid = document.getElementById("topicsGrid");
  const title = document.querySelector("#topics .section-title");
  if (!grid) return;
  const selectedSubject = document.getElementById("subjectFilter")?.value || "all";
  if (selectedSubject !== "all") applySubjectTheme(selectedSubject);
  const visibleTopics = selectedSubject === "all" ? topics : topics.filter(topic => (topic.subject || "FAR") === selectedSubject);
  const existingChips = document.getElementById("subjectChipMount");
  if (existingChips) existingChips.remove();
  const existingNotice = document.getElementById("subjectThemeNotice");
  if (existingNotice) existingNotice.remove();
  grid.innerHTML = visibleTopics.map(topic => {
    const intro = (topic.discussion || "Open this topic to view the available lesson menu tabs.").slice(0, 140);
    const subjectId = topic.subject || "FAR";
    return `
      <article class="card subject-card" style="--subject-primary:${getSubjectColor(subjectId)}">
        <span class="subject-badge" style="background:${getSubjectColor(subjectId)}">${escapeHtml(subjectId)}</span>
        <h3>${escapeHtml(topic.title)}</h3>
        <p>${escapeHtml(intro)}${intro.length >= 140 ? "..." : ""}</p>
        <button class="btn primary" style="background:${getSubjectColor(subjectId)}" onclick="openTopic('${topic.id}')">Open Topic</button>
      </article>
    `;
  }).join("") || "<p>No topics found for this subject.</p>";
}
function getSubjectColor(subjectId) {
  const colors = { FAR: "#0b63ce", AFAR: "#0f7a3b", MAS: "#6d28d9", TAX: "#b42318", RFBT: "#c05600", AUD: "#b7791f" };
  return colors[String(subjectId).toUpperCase()] || "#0b63ce";
}

/* Override openTopic so clicked topic also changes subject background */
const originalOpenTopicForTheme = typeof openTopic === "function" ? openTopic : null;
function openTopic(topicId, initialLessonId = null) {
  currentOpenTopicId = topicId;
  const topic = ensureTopicShape(topics.find(t => t.id === topicId));
  if (topic?.subject) applySubjectTheme(topic.subject);
  const content = document.getElementById("topicContent");
  const customTabs = topic.tabs || [];
  const firstLessonId = customTabs[0]?.id || null;
  currentOpenLessonId = initialLessonId || firstLessonId;
  const menuItems = customTabs.map(tab => ({ id: tab.id, title: tab.title }));
  const menuButtons = menuItems.map(item => `
      <button type="button" class="lesson-menu-btn" data-lesson-id="${escapeHtml(item.id)}" onclick="showTopicLesson('${escapeJs(topic.id)}', '${escapeJs(item.id)}')">${escapeHtml(item.title)}</button>
    `).join("");

  content.innerHTML = `
    <aside class="topic-side" style="border-top:5px solid ${getSubjectColor(topic.subject)}">
      <span class="subject-badge" style="background:${getSubjectColor(topic.subject)}">${escapeHtml(topic.subject || "FAR")}</span>
      <h3>Lesson Menu</h3>
      <p class="muted-text small-note">Click one lesson tab to view its content.</p>
      ${menuButtons}
    </aside>
    <article class="topic-main">
      <h2 style="color:${getSubjectColor(topic.subject)}">${escapeHtml(topic.title)}</h2>
      <div id="activeLessonContent" class="active-lesson-content"></div>
    </article>
  `;
  showPage("topic-detail");
  showTopicLesson(topic.id, currentOpenLessonId);
  localStorage.setItem(getStudentStorageKey("lastLesson"), JSON.stringify({ topicId: topic.id, lessonId: currentOpenLessonId }));
}

/* Student preview also demonstrates subject-specific background color */
const originalRenderStudentViewPreviewForTheme = typeof renderStudentViewPreview === "function" ? renderStudentViewPreview : null;
function renderStudentViewPreview(mode = "dashboard") {
  if (currentUser?.role !== "admin") return alert("Admin access only.");
  const box = document.getElementById("studentViewPreviewBox");
  if (!box) return;
  const approvedQuestions = quizBank.filter(q => (q.reviewStatus || "approved") === "approved");
  if (mode === "dashboard") {
    clearSubjectTheme();
    box.innerHTML = `
      <div class="preview-frame">
        <div class="preview-header">
          <span class="preview-badge">Student View</span>
          <h2>Student Dashboard</h2>
          <p>Students choose a subject to view the related topics and theme.</p>
        </div>
        <div class="subject-chip-row">
          ${SUBJECTS.map(s => `<button class="subject-chip" type="button" onclick="renderStudentViewPreview('subject-${s.id}')">${s.id}</button>`).join("")}
        </div>
        <div class="cards-grid preview-cards-grid">
          <div class="card"><h3>Study Topics</h3><p>Read discussions and lesson tabs.</p><button class="btn primary" type="button" onclick="renderStudentViewPreview('topics')">Open Topics</button></div>
          <div class="card"><h3>Take Quiz</h3><p>Create theory or problem-solving quizzes.</p><button class="btn primary" type="button" onclick="renderStudentViewPreview('quizzer')">Open Quizzer</button></div>
          <div class="card"><h3>Account Role</h3><p>Logged in as student.</p><p>Trial and quiz credit status appears here.</p></div>
        </div>
      </div>`;
    return;
  }
  if (String(mode).startsWith("subject-")) {
    const subjectId = String(mode).replace("subject-", "");
    applySubjectTheme(subjectId);
    const subjectTopics = topics.filter(t => (t.subject || "FAR") === subjectId);
    box.innerHTML = `
      <div class="preview-frame">
        <div class="preview-header">
          <span class="preview-badge">Student View</span>
          <h2>${escapeHtml(subjectId)} Subject Theme</h2>
          <p>Students now see ${escapeHtml(subjectId)} topics with the subject color theme.</p>
        </div>
        <div class="subject-chip-row">
          ${SUBJECTS.map(s => `<button class="subject-chip ${s.id === subjectId ? "active-subject" : ""}" type="button" onclick="renderStudentViewPreview('subject-${s.id}')">${s.id}</button>`).join("")}
        </div>
        <div class="cards-grid preview-cards-grid">
          ${subjectTopics.map(topic => `<div class="card subject-card" style="--subject-primary:${getSubjectColor(subjectId)}"><span class="subject-badge" style="background:${getSubjectColor(subjectId)}">${subjectId}</span><h3>${escapeHtml(topic.title)}</h3><p>${escapeHtml((topic.discussion || "").slice(0, 120))}</p><button class="btn primary" style="background:${getSubjectColor(subjectId)}" onclick="renderStudentPreviewTopic('${topic.id}')">Preview Topic</button></div>`).join("") || "<p>No topics yet.</p>"}
        </div>
      </div>`;
    return;
  }
  if (mode === "topics") {
    const selected = document.getElementById("subjectFilter")?.value || "all";
    if (selected !== "all") applySubjectTheme(selected);
    box.innerHTML = `
      <div class="preview-frame">
        <div class="preview-header">
          <span class="preview-badge">Student View</span>
          <h2>Choose a Subject</h2>
          <p>Click any subject below to see its background color.</p>
        </div>
        <div class="subject-chip-row">
          ${SUBJECTS.map(s => `<button class="subject-chip" type="button" onclick="renderStudentViewPreview('subject-${s.id}')">${s.id}</button>`).join("")}
        </div>
      </div>`;
    return;
  }
  if (originalRenderStudentViewPreviewForTheme) return originalRenderStudentViewPreviewForTheme(mode);
}

